/* Quiz pools, keyed by chapter slug. Schema: CLAUDE.md §9.
   window.QUIZ_POOLS[slug] = [{ id, type, question, options, answerIndex, explanation }]
   type is one of: concept | scenario | bug | compare */
window.QUIZ_POOLS = {
  "how-to-use-this-course": [
    { id: "htuc-01", type: "concept", question: "What does \"mastery\" mean in this course's own definition, as stated in chapter 0?", options: ["Being able to navigate the Keycloak admin console from memory", "Being able to explain why Keycloak is built the way it is, not just where its buttons are", "Passing every chapter quiz with a perfect score", "Memorizing every RFC referenced in the deep-dive links"], answerIndex: 1, explanation: "The course explicitly frames mastery as explaining the underlying IAM concept behind a Keycloak feature, not just operating the console." },
    { id: "htuc-02", type: "concept", question: "Where is your quiz score for a chapter actually stored?", options: ["On the course's server, tied to your account", "In a cookie that syncs across devices", "In your browser's localStorage, under a key like iam:quiz:<slug>", "Nowhere — scores are not retained between visits"], answerIndex: 2, explanation: "There is no server or account. QuizEngine reads/writes a per-chapter localStorage key such as iam:quiz:how-to-use-this-course." },
    { id: "htuc-03", type: "concept", question: "Which chapter contains the first hands-on lab against a real, running Keycloak instance?", options: ["Chapter 1", "Chapter 13", "Chapter 20", "Chapter 31"], answerIndex: 2, explanation: "Parts I-III (chapters 1-18) are concept-only; chapter 20, opening Part IV, is the first real Keycloak lab." },
    { id: "htuc-04", type: "concept", question: "According to this chapter's pitfall callout, what should you avoid doing before chapter 20?", options: ["Installing Docker", "Installing a JDK", "Installing and running Keycloak itself", "Installing curl or Postman"], answerIndex: 2, explanation: "The course deliberately delays Keycloak installation until chapter 20 so the concept chapters build a mental model first; installing it early tends to produce button-clicking without context." },
    { id: "htuc-05", type: "scenario", question: "A reader clears their browser's site data between sessions and finds all their quiz scores reset to zero. What's the most accurate explanation?", options: ["This is a bug in QuizEngine that should be reported", "Scores are stored only in that browser's localStorage, which clearing site data erases, and there's no other copy", "Scores are tied to the reader's IP address, which changed", "Quiz scores expire automatically after 24 hours"], answerIndex: 1, explanation: "There's no server-side copy of progress — localStorage is the only place scores live, so clearing it (or switching browsers/devices) loses them." },
    { id: "htuc-06", type: "scenario", question: "A reader is three chapters into Part I and has no Docker containers running at all. Should they be worried they've missed a setup step?", options: ["Yes, every chapter requires Keycloak running in the background", "No, Parts I-III are concept-only and need no Keycloak instance; the first lab is chapter 20", "Yes, but only if they skipped chapter 0's Docker installation", "No, but they should at least have Postman open"], answerIndex: 1, explanation: "Part I-III chapters are explicitly concept-only per chapter 0 — nothing needs to be running yet." },
    { id: "htuc-07", type: "concept", question: "What happens when you retake a chapter's quiz a second time?", options: ["You get the exact same questions in the exact same order", "A random subset of the pool is drawn again and both question order and each question's answer options are reshuffled", "The quiz becomes permanently locked after the first attempt", "Your previous best score is discarded and only the new attempt counts"], answerIndex: 1, explanation: "QuizEngine shuffles the pool, takes a subset, and shuffles each question's option order on every render — and it tracks best score across attempts, not just the latest." },
    { id: "htuc-08", type: "concept", question: "What is the stated purpose of the \"self-check\" questions that appear before the graded quiz in every chapter?", options: ["They are a harder, bonus version of the quiz", "They are open-ended thinking prompts with no shown answer, meant to be answered before the graded quiz", "They replace the quiz for chapters with no lab", "They are auto-graded along with the quiz"], answerIndex: 1, explanation: "Self-check questions have no inline answer shown — they're a check on your own understanding, separate from the scored quiz." },
    { id: "htuc-09", type: "concept", question: "How many Parts does the full 50-chapter curriculum have (including Part 0 orientation)?", options: ["8", "9", "11", "14"], answerIndex: 2, explanation: "Part 0 (orientation) plus Parts I through XI makes 11 Parts total." },
    { id: "htuc-10", type: "scenario", question: "A reader asks why the course doesn't let them skip straight to the Keycloak chapters since that's the product they actually want to learn. What's the course's own argument against doing that?", options: ["The Keycloak chapters technically require completing the quizzes from Parts I-III to unlock", "Keycloak chapters assume the Part I-III concepts and only recall them in one paragraph; skipping them risks being able to configure Keycloak without being able to explain why any of it works that way", "Keycloak chapters are harder and need the extra practice time from earlier chapters", "There is no argument — skipping ahead is explicitly supported and encouraged"], answerIndex: 1, explanation: "The course's stated failure mode is exactly this: knowing how to click through the console without understanding the underlying IAM concept." },
    { id: "htuc-11", type: "concept", question: "Which two commands does chapter 0 ask you to run right now, in its \"Try it\" callout, just to confirm your environment?", options: ["kcadm.sh --version and keycloak --version", "docker --version and java -version", "curl --version and postman --version", "node --version and python --version"], answerIndex: 1, explanation: "The try-it callout asks only for docker --version and java -version — confirming the two tools needed starting Part IV, without installing or configuring anything yet." },
    { id: "htuc-12", type: "scenario", question: "Starting in chapter 2, a quiz question references \"Riverside Health\" without further introduction. What should a reader who only read chapter 0 expect?", options: ["This is an error — chapter 0 should have defined Riverside Health already", "It's one of three recurring fictional organizations previewed in chapter 0 and formally introduced with detail in chapter 2", "It refers to a real healthcare company the course is case-studying", "It's unrelated background flavor text with no bearing on the question"], answerIndex: 1, explanation: "Chapter 0 deliberately previews the three orgs by name only, leaving Northwind/Riverside/Meridian's actual details to chapter 2, which owns that introduction." }
  ],

  "what-is-iam": [
    { id: "wii-01", type: "concept", question: "What is the core problem IAM exists to solve?", options: ["Making login pages visually consistent across apps", "Answering \"who is this\" and \"what can they do\" once, centrally, instead of per application", "Replacing passwords entirely with biometrics", "Reducing the number of applications a company runs"], answerIndex: 1, explanation: "IAM is fundamentally a de-duplication strategy for the authentication and authorization problem, not primarily a UI or password-elimination concern." },
    { id: "wii-02", type: "concept", question: "Which one-sentence description correctly distinguishes authentication from authorization?", options: ["Authentication decides what you can do; authorization proves who you are", "Authentication proves who you are; authorization decides what you can do", "They are two names for the same process", "Authentication only applies to passwords; authorization only applies to tokens"], answerIndex: 1, explanation: "Authentication answers \"who are you?\"; authorization answers \"what are you allowed to do, now that I know who you are?\" Chapter 3 covers both in depth." },
    { id: "wii-03", type: "scenario", question: "A company has ten internal applications, each built by a different team at a different time, each with its own login form and password storage. What is the most likely outcome described in this chapter, rather than ten solid independent login systems?", options: ["Ten identical, interchangeable login systems", "Ten slightly different login systems with uneven security quality and no shared audit trail", "One team eventually builds all ten logins to a consistent standard", "The applications automatically converge on a shared password store"], answerIndex: 1, explanation: "Without centralization, each team solves the same problem independently, at different quality levels, producing inconsistent security and no single audit answer." },
    { id: "wii-04", type: "compare", question: "How does identity brokering differ from federation, as introduced in this chapter?", options: ["Brokering delegates authentication to an external identity provider; federation connects to an existing external identity store like LDAP", "They are the same concept with different names", "Brokering only works with passwords; federation only works with biometrics", "Federation is a Keycloak-specific feature; brokering is vendor-agnostic"], answerIndex: 0, explanation: "Brokering is about delegating the authentication act itself (e.g. \"Login with Google\"); federation is about reusing an existing identity store's accounts and credentials. Both are covered in depth in chapter 7." },
    { id: "wii-05", type: "concept", question: "Which of the following is NOT listed in this chapter as part of the common IAM feature set?", options: ["Single Sign-On", "Self-service account management", "Fine-grained authorization", "Automatic code deployment pipelines"], answerIndex: 3, explanation: "Deployment pipelines are unrelated to IAM's feature set; SSO, self-service, and fine-grained authorization are all standard IAM capabilities covered in this chapter." },
    { id: "wii-06", type: "scenario", question: "Priya has access to three applications (HR portal, wiki, reporting dashboard) through one centrally managed identity. On her last day, an administrator disables that one identity. What happens?", options: ["Nothing changes until each app's admin separately disables her account", "Access to all three applications is revoked at once, from a single action", "Only the HR portal access is revoked automatically", "She retains read-only access to all three apps indefinitely"], answerIndex: 1, explanation: "This is the core benefit of centralized identity: disabling one identity propagates access removal everywhere that identity was trusted, instead of requiring N separate offboarding steps." },
    { id: "wii-07", type: "concept", question: "According to this chapter, is adopting a centralized IAM system equivalent to \"being secure\"?", options: ["Yes, IAM adoption automatically eliminates security risk", "No — it removes a recurring source of bugs but introduces its own configuration surface that must be secured carefully", "No, IAM systems are inherently less secure than per-app authentication", "Yes, as long as MFA is enabled"], answerIndex: 1, explanation: "The pitfall callout explicitly warns that centralizing authentication relocates risk to a new configuration surface (e.g. redirect URIs, role mappings) rather than eliminating it." },
    { id: "wii-08", type: "scenario", question: "A small internal tool has one trusted admin user and no plans to add more applications or users. Per this chapter's guidance, should the team adopt a full centralized IAM system?", options: ["Yes, always — IAM should be adopted for every application regardless of scale", "Probably not — this is a case where a dedicated IAM system is likely overkill", "Only if the tool uses passwords instead of SSH keys", "Yes, but only if the company has more than 50 employees"], answerIndex: 1, explanation: "The chapter explicitly lists a single small internal tool with a handful of trusted users as a legitimate case where full IAM adoption is overkill." },
    { id: "wii-09", type: "compare", question: "Which pairing correctly reflects a trade-off of adopting a centralized IAM system, per this chapter's pros/cons table?", options: ["Pro: reduces the chance of building authentication wrong — Con: introduces a new single point of failure if the IAM system goes down", "Pro: eliminates all operational overhead — Con: makes offboarding slower", "Pro: removes the need for audit trails — Con: requires more passwords per user", "Pro: guarantees compliance — Con: has no learning curve"], answerIndex: 0, explanation: "Centralizing reduces inconsistent, error-prone per-app authentication logic, but also means that if the shared IAM system is unavailable, every connected application's login is unavailable too." },
    { id: "wii-10", type: "concept", question: "What does an \"audit trail,\" as described in this chapter, primarily let an organization do?", options: ["Automatically fix misconfigured redirect URIs", "Answer \"who accessed what, and when\" consistently across connected applications", "Generate password reset emails", "Enforce multi-factor authentication"], answerIndex: 1, explanation: "A centralized audit trail consolidates authentication and access events into one consistent record, instead of scattering them across each application's own (or absent) logging." },
    { id: "wii-11", type: "scenario", question: "An enterprise customer wants to log in to a SaaS vendor's product using their own corporate directory rather than creating a new password. Which IAM capability, introduced in this chapter, most directly addresses this?", options: ["Self-service account management", "Federation / identity brokering with an external identity provider", "Password expiration policy", "Admin console audit logging"], answerIndex: 1, explanation: "Federation and identity brokering exist precisely to let users authenticate via an external directory or identity provider instead of creating yet another standalone credential." },
    { id: "wii-12", type: "concept", question: "Per this chapter, where does Keycloak fit relative to the IAM concepts being taught?", options: ["Keycloak defines what IAM is; the concepts only apply to Keycloak", "Keycloak is this course's chosen implementation vehicle for vendor-agnostic IAM concepts; other products (Okta, Auth0, Entra ID, Ping) implement the same ideas differently", "Keycloak is a compliance framework, not an IAM product", "Keycloak only handles authorization, not authentication"], answerIndex: 1, explanation: "The chapter is explicit that Keycloak is one of several mature IAM products implementing these ideas, with the wider market comparison deferred to chapter 12." },
    { id: "wii-13", type: "scenario", question: "A mobile app needs a secure, standardized way to prove to a backend API that its user is logged in, without inventing a custom session-cookie scheme. What does centralized IAM typically provide for this?", options: ["A custom per-app cookie format", "Standardized, interoperable tokens, covered in depth in Part III", "A shared plaintext password file", "Nothing — mobile apps must build this themselves"], answerIndex: 1, explanation: "Standardized tokens are one of the problems listed in the \"why centralizing matters\" table — mobile and API clients get an interoperable, standard way to carry proof of authentication instead of ad-hoc per-app schemes." },
    { id: "wii-14", type: "compare", question: "How does Workforce IAM differ from CIAM, as briefly introduced in this chapter?", options: ["Workforce IAM manages an organization's own employees/internal access; CIAM manages external customer-facing identities", "Workforce IAM is cloud-only; CIAM is on-premises only", "CIAM only supports SAML; Workforce IAM only supports OIDC", "They are identical, just different marketing terms"], answerIndex: 0, explanation: "Workforce IAM targets internal employee/system access, while CIAM targets external customers at consumer scale — chapter 12 covers this distinction in depth." },
    { id: "wii-15", type: "concept", question: "What does \"extensibility\" (or plugin architecture) mean in the context of an IAM system, per this chapter?", options: ["The ability to add more passwords per user", "The ability to customize authentication steps, data sources, or branding via a defined plugin interface instead of forking the product", "The ability to run on more servers simultaneously", "The ability to support more languages in the login page only"], answerIndex: 1, explanation: "Extensibility refers to a plugin/SPI-style architecture for customization without modifying the core product — Keycloak's version of this is covered in Part VIII." },
    { id: "wii-16", type: "scenario", question: "A compliance auditor asks a company using ten disconnected, home-grown login systems: \"who had access to the patient database last quarter?\" Based on this chapter, what is the most likely problem?", options: ["The company can answer instantly from a single audit log", "There is no single consistent answer, because access and logging are scattered across separate, uncoordinated systems", "The question is irrelevant to IAM", "Only the database administrator needs to answer this, not the application teams"], answerIndex: 1, explanation: "One of the core problems centralized IAM solves is exactly this: without it, there's no single, consistent audit trail spanning all applications." },
    { id: "wii-17", type: "concept", question: "Per this chapter, which statement about MFA within the IAM feature set is accurate?", options: ["MFA replaces authentication entirely and makes passwords unnecessary", "MFA requires more than one proof of identity, such as a password plus a one-time code or hardware key", "MFA is a form of authorization, not authentication", "MFA is unique to Keycloak and not found in other IAM products"], answerIndex: 1, explanation: "MFA adds additional authentication factors beyond (or instead of) a password alone; it is a standard, vendor-agnostic IAM capability, covered in depth in chapter 5." },
    { id: "wii-18", type: "compare", question: "Which best contrasts the \"without centralized IAM\" and \"with centralized IAM\" worlds for handling a departing employee?", options: ["Without IAM: one action disables access everywhere. With IAM: access must be revoked in each system separately", "Without IAM: access must be chased down and revoked in each separate system. With IAM: disabling one identity removes access everywhere it's connected", "Both worlds require exactly the same offboarding effort", "Centralized IAM has no effect on offboarding"], answerIndex: 1, explanation: "This is one of the clearest wins of centralization: offboarding collapses from N separate actions into one, as illustrated by the Priya example and the comparison table." }
  ],

  "identity-fundamentals": [
    { id: "idf-01", type: "concept", question: "Jane Doe's system record lists her identifier as jane.doe@northwindapps.com. Which of the following is also true of an identifier, by definition?", options: ["It must remain secret at all times", "It uniquely designates the identity for lookup within some namespace", "It changes every time the credential is rotated", "It always expires after a fixed lifetime"], answerIndex: 1, explanation: "An identifier only needs to be unique within its namespace; unlike a credential, it does not need to stay secret." },
    { id: "idf-02", type: "scenario", question: "At Meridian Trust, a teller is asked to enter a one-time code generated by an authenticator app in addition to her password before approving a wire transfer. In IAM terms, what role does that one-time code play?", options: ["It's an attribute", "It's an identifier", "It's a credential — evidence she controls a factor tied to her identity", "It's a principal"], answerIndex: 2, explanation: "A one-time code is evidence of control over a factor, which makes it a credential, just like a password." },
    { id: "idf-03", type: "scenario", question: "Riverside Health records patientsPortalEnabled: true as a flag on certain patient identities to control which app features they see. What IAM concept does this flag represent?", options: ["Credential", "Attribute — a recorded fact about the identity", "Identifier", "Subject"], answerIndex: 1, explanation: "A flag that describes the identity rather than proving control of it is an attribute, not a credential." },
    { id: "idf-04", type: "compare", question: "What is the formal distinction between a principal and a subject?", options: ["A principal is always a human; a subject is always a machine", "A principal is the entity being identified; a subject is that entity as represented in an active security context such as a token or session", "A subject always outlives the principal it represents", "There is no distinction — the terms are fully interchangeable in every IAM specification"], answerIndex: 1, explanation: "The principal is the real-world entity; the subject is that entity inside one active context, like a specific token." },
    { id: "idf-05", type: "scenario", question: "Jane logs into Northwind Apps and gets an access token. Later her session expires and she logs in again, getting a new token. Across these two logins, what stayed the same and what changed?", options: ["The principal changed; the subject stayed the same", "Both the principal and the subject changed completely", "The principal (Jane, the real identity) stayed the same; a new subject (a new token/session context) was created each time she authenticated", "Neither changed — tokens are principals"], answerIndex: 2, explanation: "One principal can produce many subjects over time, one per authentication event." },
    { id: "idf-06", type: "scenario", question: "Riverside Health's HR-integrated system has an admin create a new nurse's account before her first day, rather than letting her sign up herself. Which lifecycle entry point does this describe?", options: ["Self-registration", "Federated/brokered creation", "Manual creation", "Deprovisioning"], answerIndex: 2, explanation: "An administrator directly creating the account ahead of time is manual creation." },
    { id: "idf-07", type: "scenario", question: "Meridian Trust's fraud team flags suspicious activity on a teller's account and temporarily blocks her login while HR investigates, planning to restore access if she's cleared. Which lifecycle stage is this?", options: ["Delete", "Modify", "Suspend", "Activate"], answerIndex: 2, explanation: "Blocking access temporarily, with the possibility of reinstatement, is the suspend stage." },
    { id: "idf-08", type: "concept", question: "In the generalized identity lifecycle this chapter describes, which is the correct order of stages?", options: ["Activate → Create → Suspend → Modify → Delete", "Create → Activate → Modify → Suspend → Delete", "Create → Suspend → Activate → Delete → Modify", "Modify → Create → Activate → Delete → Suspend"], answerIndex: 1, explanation: "The generalized order is create, activate, modify, suspend, delete." },
    { id: "idf-09", type: "scenario", question: "A prospective customer signs up for a free Northwind Apps trial by filling out a signup form directly on Northwind's marketing site. Which entry point created this identity?", options: ["Manual creation", "Self-registration", "Federated/brokered creation", "Deprovisioning"], answerIndex: 1, explanation: "The principal created her own identity through a signup form, which is self-registration." },
    { id: "idf-10", type: "scenario", question: "Riverside Health's lab-results integration runs under a dedicated account that polls an imaging system every five minutes, with no human ever entering a password for it. What kind of identity is this?", options: ["Human identity", "A principal without a subject", "Service account / machine identity", "A self-registered identity"], answerIndex: 2, explanation: "An unattended account used by an automated process is a non-human identity — a service account." },
    { id: "idf-11", type: "concept", question: "Why does distinguishing human from non-human identities matter in practice?", options: ["Non-human identities never need any access controls", "Service accounts and workload identities often have long-lived, broad, or unattended access, so reviewing and least-privileging them requires different processes than reviewing a human employee's access", "Human identities are always more privileged than service accounts", "The distinction is purely cosmetic and has no security implications"], answerIndex: 1, explanation: "Non-human identities tend to be long-lived and unattended, which creates distinct governance risk." },
    { id: "idf-12", type: "compare", question: "A user logs into Northwind Apps for the first time by clicking 'Sign in with Microsoft,' and Northwind creates a local record for her automatically from the data Microsoft returns. Which entry point is this, and how does it differ from self-registration?", options: ["Self-registration — identical to filling out a signup form", "Federated/brokered creation — the identity is created automatically from an external identity provider's assertion rather than the user filling out a form directly", "Manual creation — an admin created it in advance", "Deprovisioning — the account is being removed"], answerIndex: 1, explanation: "Federated/brokered creation builds the local identity from an external IdP's data on first login, unlike a self-filled signup form." },
    { id: "idf-13", type: "concept", question: "In IAM terms, what is deprovisioning?", options: ["Creating a new identity for an employee's first day", "The process of removing or disabling an identity's access, typically at the end of its lifecycle (e.g., when an employee leaves)", "Issuing a new credential to replace an expired one", "Adding a new attribute to an existing identity"], answerIndex: 1, explanation: "Deprovisioning is removing or disabling access at the end of the identity lifecycle." },
    { id: "idf-14", type: "scenario", question: "Meridian Trust's auditors specifically want to know whether a flagged account was suspended-then-reinstated or deleted-then-recreated. Why does this distinction matter for an audit trail?", options: ["It doesn't matter — both produce identical records", "Suspend-then-reinstate preserves the original identity record and its history under one continuous identifier, while delete-then-recreate breaks that continuity and can obscure that it's the same real-world person", "Deletion is always reversible, so there's no difference", "Suspension always permanently deletes credentials"], answerIndex: 1, explanation: "Suspend preserves continuity of the record; delete-and-recreate breaks it, which matters for audit trails." },
    { id: "idf-15", type: "concept", question: "For the same person, which pairing correctly matches concept to example?", options: ["Identity = jane.doe@northwindapps.com; Identifier = Jane's full account record", "Credential = department: Engineering; Attribute = her password", "Identity = the full record representing 'Jane Doe, Northwind engineer'; Identifier = jane.doe@northwindapps.com; Credential = her password/OTP; Attribute = department: Engineering", "All four terms describe the same thing and are interchangeable"], answerIndex: 2, explanation: "Identity is the whole record, identifier is the lookup handle, credential is proof of control, and attribute is a recorded fact." },
    { id: "idf-16", type: "scenario", question: "A Northwind Apps access token is stolen and used by an attacker before it expires. In principal/subject terms, what happened?", options: ["The principal (Jane) was compromised directly; no subject was involved", "The attacker became a new principal", "The attacker gained control of a valid subject (the active session/token) without being the principal it was issued to", "Nothing changed, since principal and subject are identical"], answerIndex: 2, explanation: "Token theft compromises a subject (one active context), not the underlying principal, which is why the two concepts matter separately for incident response." }
  ],

  "authn-authz-accounting": [
    { id: "aaa-01", type: "concept", question: "In the formal AAA model, what question does the \"Accounting\" part answer?", options: ["Who are you?", "What are you allowed to do?", "What did you actually do, and when?", "Should this request be rate-limited?"], answerIndex: 2, explanation: "Accounting is the real-time recording of identity and access events — what happened, and when — distinct from the authentication (\"who\") and authorization (\"what can\") questions." },
    { id: "aaa-02", type: "concept", question: "What is the most accurate way to describe the relationship between accounting and audit?", options: ["They are two names for the exact same activity", "Accounting is the real-time recording act; audit is the later review of what was recorded", "Audit happens first and accounting happens afterward", "Accounting only applies to billing, audit only applies to security"], answerIndex: 1, explanation: "Accounting continuously records events as they occur; audit is a separate, later activity (scheduled or incident-triggered) that reviews those recorded events." },
    { id: "aaa-03", type: "concept", question: "Why does this chapter flag \"accounting\" as a term with some terminology ambiguity across fields?", options: ["Because it's a deprecated term nobody uses anymore", "Because in classic RADIUS/network-access contexts it leans toward usage metering for billing, while general modern IAM usage leans toward security-event logging", "Because only Keycloak uses the term", "Because accounting and authentication are legally synonymous"], answerIndex: 1, explanation: "The chapter is explicit that RADIUS-style usage of \"accounting\" (metering for billing/capacity) differs from the broader, security-logging sense most modern IAM writing uses." },
    { id: "aaa-04", type: "scenario", question: "Maria authenticates into Riverside Health's patient portal with a correct password and MFA code, then edits a URL to view a different patient's chart and succeeds. What failed?", options: ["Authentication — her credentials should have been rejected", "Authorization — the system never checked whether she has a care relationship with that patient", "Accounting — the event wasn't logged", "Nothing failed; this is expected behavior"], answerIndex: 1, explanation: "Her authentication was flawless. The system never asked the authorization question of whether she specifically may view that patient's record — a classic insecure-direct-object-reference-style authorization failure." },
    { id: "aaa-05", type: "bug", question: "A developer writes: `if (isLoggedIn(session)) { return db.getChart(patientId); }`. What is the specific bug?", options: ["The session check is performed in the wrong order", "It uses authentication as a substitute for authorization — it never checks whether this specific user may access this specific patientId", "It's missing a database index", "It incorrectly logs the access event twice"], answerIndex: 1, explanation: "This is the chapter's canonical AuthN/AuthZ conflation bug: a valid login is treated as sufficient to serve any record, when a separate permission/ownership check was required." },
    { id: "aaa-06", type: "bug", question: "A developer writes: `if (hasRole(user, \"employee\")) { invoices.approve(invoiceId); }`. Is this the same bug as checking `isLoggedIn`?", options: ["Yes, it's identical — both skip authorization entirely", "No — this one does perform an authorization check, but the check is scoped too broadly (any employee, instead of this specific employee for this specific invoice)", "No — this one is actually a correct and sufficiently scoped check", "Yes, because \"employee\" is an authentication role, not an authorization role"], answerIndex: 1, explanation: "This is a distinct bug from pure AuthN/AuthZ conflation: the shape is correct (it is a permission check), but the granularity is wrong — it authorizes at too broad a scope." },
    { id: "aaa-07", type: "scenario", question: "A Northwind Apps engineer at customer tenant \"Acme Corp\" authenticates successfully, but the backend only checks \"does this user belong to some paying tenant\" rather than \"does this user belong to this specific tenant\" before returning dashboard data. What's at risk?", options: ["Nothing — tenant checks aren't an IAM concern", "Cross-tenant data exposure — she could potentially view another customer's dashboard despite authenticating correctly", "Only her own data is at risk", "This is purely an accounting/audit-trail problem"], answerIndex: 1, explanation: "This mirrors the IDOR pattern: correct authentication, but an authorization check scoped incorrectly (any tenant instead of this specific tenant) exposes cross-tenant data." },
    { id: "aaa-08", type: "concept", question: "Which of these is a correct pairing of AAA question to example?", options: ["Authentication — \"does jane.doe have permission to approve this invoice?\"", "Authorization — \"is this password correct for jane.doe?\"", "Accounting — \"record that jane.doe approved invoice #4821 at 14:02 UTC\"", "Audit — \"issue jane.doe a one-time code\""], answerIndex: 2, explanation: "Accounting is the act of recording what happened, as structured timestamped data — exactly the invoice-approval log example." },
    { id: "aaa-09", type: "scenario", question: "HIPAA requires Riverside Health to be able to tell a patient exactly who accessed their chart and when, on request. Which part of AAA does this directly depend on?", options: ["Authentication only", "Authorization only", "Accounting — without continuous event recording, there is nothing to answer the request from", "None of AAA; this is purely a database backup requirement"], answerIndex: 2, explanation: "HIPAA's access-accounting requirement depends on Riverside having recorded (accounted for) every access as it happened — it can't be reconstructed after the fact without that trail." },
    { id: "aaa-10", type: "scenario", question: "Meridian Trust's PCI-DSS obligations require tracking and monitoring access to cardholder data. If Meridian has rigorous accounting but never actually reviews the resulting logs, what is missing?", options: ["Authentication", "Authorization", "Audit — the review step that compliance and assessors actually require, not just the raw recorded data", "Nothing is missing; recording alone satisfies PCI-DSS"], answerIndex: 2, explanation: "PCI-DSS expects both tracking (accounting) and regular review (audit) of access logs — accounting alone, unreviewed, doesn't satisfy the monitoring expectation." },
    { id: "aaa-11", type: "compare", question: "How does an authentication failure differ from an authorization failure, in terms of what an attacker needs?", options: ["They require the same attacker capability in all cases", "An authentication failure typically means proving a false identity (stolen/guessed credentials); an authorization failure can happen even with a fully legitimate, correctly authenticated identity", "Authorization failures only happen to administrators", "Authentication failures are always worse than authorization failures"], answerIndex: 1, explanation: "The chapter's running point: authorization failures (like IDOR) often require no stolen credentials at all — the attacker may be a fully legitimate, correctly authenticated user exploiting a missing permission check." },
    { id: "aaa-12", type: "concept", question: "In Keycloak, where does the \"Accounting\" part of AAA map most directly?", options: ["The Authentication flows screen", "The Roles and Groups screens", "The realm's Events subsystem (Realm settings → Events)", "The Clients screen"], answerIndex: 2, explanation: "Keycloak's Events subsystem records login and administrative actions — the concrete implementation of accounting. Full depth in chapter 28." },
    { id: "aaa-13", type: "bug", question: "A team says \"we have an audit trail\" but it turns out they only have generic web-server access logs (IP, URL, timestamp — no identity or permission context). What's the mistake?", options: ["There is no mistake — any log is an audit trail", "Conflating generic infrastructure logging with deliberate AAA-style accounting of identity and permission events — they overlap but aren't the same thing", "Web server logs are always sufficient for HIPAA and PCI-DSS", "This is an authentication bug, not an accounting bug"], answerIndex: 1, explanation: "The chapter's common-mistakes list calls this out directly: generic access logs are not the same as deliberate, identity-aware accounting data." },
    { id: "aaa-14", type: "scenario", question: "An attacker guesses a weak password and logs in as Jane (an authentication failure occurred), but a tight permission check on the one sensitive action they try still blocks them. What does this illustrate?", options: ["That authorization is irrelevant once authentication fails", "That authorization can act as an independent safety net even when authentication has already failed", "That this scenario is impossible in a real system", "That accounting should have prevented the login entirely"], answerIndex: 1, explanation: "This is the chapter's \"AuthN wrong, AuthZ correct\" quadrant: authorization, evaluated independently, can still block damage after authentication has already been compromised." },
    { id: "aaa-15", type: "concept", question: "What historical standard is most associated with popularizing the formal three-part AAA framing?", options: ["OAuth 2.0", "RADIUS (Remote Authentication Dial In User Service)", "SAML 2.0", "OpenID Connect"], answerIndex: 1, explanation: "RADIUS (RFC 2865) is the network-access-control standard most associated with formalizing Authentication, Authorization, and Accounting as a named model." },
    { id: "aaa-16", type: "compare", question: "How does this chapter's refined definition of \"audit trail\" differ from chapter 1's original one-line definition?", options: ["They are unrelated concepts with no connection", "Chapter 1's definition actually described accounting's recorded output; chapter 3 clarifies that audit itself is the separate, later review of that output", "Chapter 1's definition was about authentication, not audit", "There is no difference; the definitions are identical"], answerIndex: 1, explanation: "The chapter explicitly notes that chapter 1's audit-trail definition was describing what accounting produces, and sharpens the distinction between the recording act and the later review act." },
    { id: "aaa-17", type: "scenario", question: "A Meridian Trust teller, correctly authenticated as a bank employee, can open every customer account in the bank rather than only accounts tied to transactions they're actively handling. What is this a failure of?", options: ["Authentication — the teller shouldn't have been let in at all", "Authorization — the internal permission boundary is too broad for the teller's actual job scope", "Accounting — the teller's login wasn't logged", "This isn't a security issue since the teller is a legitimate employee"], answerIndex: 1, explanation: "The teller's authentication is entirely correct; the problem is an authorization boundary that's far too broad for what their role should actually permit." },
    { id: "aaa-18", type: "concept", question: "Why is it inaccurate to describe AuthN and AuthZ as \"basically the same check\"?", options: ["Because they always happen at completely different times, days apart", "Because a system can get one of them right while getting the other wrong — they are independently evaluated decisions that happen to be grouped under the same category of software", "Because authorization never depends on authentication at all", "Because only one of them is implemented in any real system"], answerIndex: 1, explanation: "The chapter's central point: authentication and authorization are genuinely separate decisions, each independently capable of being right or wrong, even though they're commonly bundled together conceptually." }
  ],

  "directory-services": [
    { id: "dir-01", type: "concept", question: "Which best describes a directory service?", options: ["A transactional database optimized for frequent writes", "A read-optimized, hierarchically organized store built for fast lookups about people, systems, and resources", "A synonym for any OAuth-compliant identity provider", "A caching layer that sits in front of an IAM product's token issuer"], answerIndex: 1, explanation: "Directory services are read-heavy and hierarchical, built for lookups like a phone book rather than for transactions like a bank ledger." },
    { id: "dir-02", type: "concept", question: "What is the relationship between X.500 and LDAP?", options: ["They are unrelated, competing standards from different eras", "LDAP is a lightweight, TCP/IP-based protocol for accessing directories that follow X.500's data model", "X.500 is Microsoft's proprietary successor to LDAP", "LDAP replaced X.500's data model entirely with a flat, non-hierarchical one"], answerIndex: 1, explanation: "X.500 defines the heavyweight original data model and protocols; LDAP is the lighter-weight protocol for accessing X.500-shaped directories over ordinary TCP/IP." },
    { id: "dir-03", type: "concept", question: "What does an entry's Distinguished Name (DN) represent?", options: ["A password hash stored for that entry", "The entry's full, unique path from the root of the Directory Information Tree", "A list of every attribute the entry carries", "The objectClass values assigned to the entry"], answerIndex: 1, explanation: "A DN is the entry's unique address in the DIT — the chain of RDNs from the entry up to the root." },
    { id: "dir-04", type: "scenario", question: "A nurse at Riverside Health enters her username and password into an application that authenticates against Active Directory via LDAP. Which LDAP operation is actually happening behind the scenes?", options: ["A search operation filtering entries by objectClass", "A bind operation, presenting her DN and password to the directory", "A compare operation checking her department attribute", "A modify operation updating her last-login timestamp"], answerIndex: 1, explanation: "A simple bind — presenting a DN and credential — is functionally an authentication attempt against the directory." },
    { id: "dir-05", type: "compare", question: "What is the difference between an entry's objectClass and its attributes?", options: ["They are two names for the same thing", "objectClass declares what kind of thing the entry is and which attributes it may carry; attributes are the actual facts recorded on it", "objectClass stores credentials; attributes store the DN", "attributes determine the entry's position in the DIT; objectClass does not"], answerIndex: 1, explanation: "objectClass is a type declaration (person, organizationalPerson, etc.); attributes are the named facts the entry actually carries, such as cn or mail." },
    { id: "dir-06", type: "scenario", question: "Northwind Apps' SaaS customers' end users log into Northwind's product every day. Where do their identities live?", options: ["In the same Active Directory as Northwind's own employees, in a dedicated OU", "In a completely separate CIAM identity store, not in Northwind's workforce Active Directory at all", "Nowhere centrally — each customer company's IT department issues its own LDAP bind credentials directly against Northwind's AD", "In Active Directory, but disabled until the customer's contract renews"], answerIndex: 1, explanation: "Northwind deliberately separates its internal workforce AD from the CIAM store holding its customers' end users — different populations, different governance." },
    { id: "dir-07", type: "concept", question: "What is a Relative Distinguished Name (RDN)?", options: ["The entire path from an entry to the root of the DIT", "The single naming component that distinguishes an entry from its siblings under the same parent", "A password hash used only for anonymous binds", "A Kerberos ticket issued by a domain controller"], answerIndex: 1, explanation: "A DN is a chain of RDNs; the RDN is just the one component distinguishing an entry from its siblings." },
    { id: "dir-08", type: "scenario", question: "Riverside Health's IT team wants clinicians and administrative staff to receive different Group Policy settings within the same Active Directory domain. What AD construct is designed for exactly this?", options: ["A separate domain controller per group", "Organizational Units (OUs), used to group objects for policy and delegated administration", "Anonymous bind scoped per department", "A second Directory Information Tree"], answerIndex: 1, explanation: "OUs exist specifically to group users/computers within one domain so different policy and administration can apply to each group." },
    { id: "dir-09", type: "concept", question: "What does a Domain Controller (DC) do in Active Directory?", options: ["It issues OAuth access tokens to connected applications", "It holds a copy of the domain's directory data and services authentication requests against it", "It stores only the DNS records for the domain, nothing else", "It is a synonym for an Organizational Unit"], answerIndex: 1, explanation: "A DC is the server holding the domain's directory data and handling authentication requests — the directory server itself in AD's vocabulary." },
    { id: "dir-10", type: "scenario", question: "A simple bind against a directory entry fails. What has been established?", options: ["The entry does not exist in the directory at all", "The presented credential was not correct for that DN — nothing more, and nothing about authorization either way", "The user's account has been permanently deleted", "The directory's schema does not permit that objectClass"], answerIndex: 1, explanation: "A bind failure just means the credential didn't match for that DN; it doesn't reveal which part was wrong, and a successful bind wouldn't have implied authorization either." },
    { id: "dir-11", type: "compare", question: "How does Active Directory relate to LDAP?", options: ["AD is unrelated to LDAP and uses a completely different data model", "AD implements the general directory-service shape and exposes an LDAP interface, while also using its own native mechanisms like Kerberos for everyday login", "LDAP is a feature that must be purchased separately and added on top of AD", "AD replaced LDAP as a protocol industry-wide"], answerIndex: 1, explanation: "AD is a concrete directory product that speaks LDAP (among other protocols) while also relying on Kerberos natively for day-to-day authentication." },
    { id: "dir-12", type: "concept", question: "What is this course's position on Kerberos?", options: ["It is covered in full cryptographic depth in this chapter", "It is AD's native authentication protocol, worth knowing exists, but deliberately out of scope for deep coverage in this course", "It is a deprecated protocol no longer used by any directory product", "It is a synonym for the LDAP bind operation"], answerIndex: 1, explanation: "The chapter explicitly flags Kerberos as AD's native protocol for day-to-day login, and explicitly scopes it out of further depth." },
    { id: "dir-13", type: "scenario", question: "Riverside Health is evaluating whether to deploy Keycloak. Its hospital already has ten thousand clinicians in an on-prem Active Directory. What does this chapter suggest is the right approach?", options: ["Migrate all ten thousand clinician accounts into Keycloak's own user store before go-live", "Connect Keycloak to the existing Active Directory via federation, so clinicians keep their existing credentials and HR keeps managing them in one place", "Disable Active Directory entirely and require clinicians to self-register in Keycloak", "Run Keycloak and Active Directory as two independent, unsynchronized sources of truth"], answerIndex: 1, explanation: "The whole point of federation (chapter 7) and Keycloak's user federation (chapter 32) is connecting to an existing authoritative directory instead of migrating its population." },
    { id: "dir-14", type: "scenario", question: "A security review finds that a production LDAP directory accepts anonymous bind for all queries, including ones that return employee phone numbers and departments. What is the most likely cause?", options: ["A deliberate, documented decision to support a public employee lookup kiosk", "A default setting nobody ever revisited, not a reasoned security decision", "A requirement of the LDAP protocol itself, which cannot be disabled", "Evidence that the directory has already been compromised"], answerIndex: 1, explanation: "Anonymous bind being left open in production is a classic case of an unreviewed default, not evidence of compromise or a documented requirement." },
    { id: "dir-15", type: "concept", question: "In chapter 2's terms, what is a directory attribute such as department or mail?", options: ["A credential, because it's stored alongside the password", "A concrete instance of the same general Attribute concept from chapter 2 — a fact recorded about an identity, not proof of anything", "A second identifier for the entry", "A synonym for the entry's Distinguished Name"], answerIndex: 1, explanation: "Directory attributes are the LDAP-specific, concrete form of chapter 2's general Attribute concept — descriptive facts, not proof." },
    { id: "dir-16", type: "scenario", question: "Meridian Trust keeps its bank employees in one Active Directory and its retail banking customers in a completely separate identity store. Why is this consistent with how Northwind Apps organizes its identities?", options: ["It isn't consistent — banks are required by PCI-DSS to use a single combined directory for all identities", "Both organizations separate their workforce directory from their customer-facing identity store, because employees and external end users are different populations with different governance needs", "Both organizations use Kerberos for both employee and customer authentication", "Meridian's structure is unrelated because it predates Northwind's CIAM store"], answerIndex: 1, explanation: "Workforce-directory vs. CIAM-store separation is a general pattern, illustrated by both Northwind and Meridian keeping employee and external-customer identities in distinct stores." },
    { id: "dir-17", type: "compare", question: "What is the key difference between an anonymous bind and a simple bind?", options: ["A simple bind is always encrypted; an anonymous bind never is", "An anonymous bind presents no credential at all; a simple bind presents a DN and a password as proof of identity", "Anonymous bind is only possible against Active Directory, never against generic LDAP", "Simple bind is used only for write operations, anonymous bind only for reads"], answerIndex: 1, explanation: "The defining difference is credential presence: simple bind authenticates with DN + password; anonymous bind authenticates with nothing, typically for unauthenticated read access." }
  ],

  "authentication-factors-mfa": [
    { id: "mfa-01", type: "concept", question: "Which three categories make up the classical authentication factors?", options: ["Knowledge, possession, inherence", "Password, PIN, biometric", "Device, location, behavior", "SMS, email, push notification"], answerIndex: 0, explanation: "Knowledge (something you know), possession (something you have), and inherence (something you are) are the three classical factor categories." },
    { id: "mfa-02", type: "scenario", question: "A system requires both a password and the answer to a security question before login. Does this qualify as genuine multi-factor authentication?", options: ["Yes, because two separate prompts are required", "No, because both are knowledge factors — compromising one method (e.g. phishing) likely compromises both", "Yes, but only if the security question is kept secret", "No, because security questions are never valid authentication factors"], answerIndex: 1, explanation: "Genuine MFA requires factors from different categories. Two knowledge factors share the same weaknesses, so defeating one tends to defeat both." },
    { id: "mfa-03", type: "concept", question: "What is the main vulnerability specific to inherence factors that doesn't apply to knowledge factors?", options: ["They can be guessed through brute force", "They cannot be rotated or reset if the stored template is compromised", "They require an internet connection to verify", "They expire automatically every 90 days"], answerIndex: 1, explanation: "A password can be changed after a breach; a compromised fingerprint or face template cannot be reissued the same way, since it corresponds to a physical trait." },
    { id: "mfa-04", type: "scenario", question: "Riverside Health's clinicians authenticate to shared workstations with a badge tap plus a short PIN. What factor category does the badge tap represent, and what is the stated trade-off for using it?", options: ["A knowledge factor, trading off memorability for cost", "A possession factor, trading off some security for speed clinicians need between patients", "An inherence factor, trading off accuracy for convenience", "A context signal, trading off accuracy for automation"], answerIndex: 1, explanation: "The badge is a possession factor. Riverside accepts a weaker standalone guarantee than full MFA in exchange for the speed clinicians need on shared workstations, compensating with session timeouts and audit logging." },
    { id: "mfa-05", type: "concept", question: "What role do context and behavior signals (device, location, typing rhythm) play in this chapter's framework?", options: ["They are a fourth classical authentication factor equal to knowledge, possession, and inherence", "They feed risk-based/adaptive authentication decisions about how much proof to demand, rather than counting as a traditional factor", "They replace the need for any authentication factor entirely", "They are only used for compliance reporting, not authentication decisions"], answerIndex: 1, explanation: "Context/behavior signals aren't proof of identity the way a factor is — they're evidence used to decide whether existing factors are sufficient or more proof should be demanded." },
    { id: "mfa-06", type: "concept", question: "In TOTP and HOTP, what is established once at enrollment and never transmitted again afterward?", options: ["The user's password", "The shared secret", "The six-digit code itself", "The user's device identifier"], answerIndex: 1, explanation: "The shared secret is set up once (often via QR code) and never sent again; both sides use it locally, combined with a moving factor, to compute matching codes." },
    { id: "mfa-07", type: "compare", question: "How does TOTP's moving factor differ from HOTP's?", options: ["TOTP uses a counter that increments on use; HOTP uses the current time", "TOTP uses the current time, rounded to a fixed step; HOTP uses a counter that increments each time a code is consumed", "They use the identical moving factor, just different code lengths", "TOTP has no moving factor; only HOTP does"], answerIndex: 1, explanation: "TOTP advances automatically with time; HOTP only advances when a code is actually used, which is also the source of its counter-desync weakness." },
    { id: "mfa-08", type: "bug", question: "A user reports their TOTP authenticator app codes are consistently rejected right after returning from an international trip. What is the most likely cause, per this chapter?", options: ["Their shared secret has become corrupted and must be reset", "Clock drift between their device and the server, since TOTP's moving factor is time-based", "The server's HOTP counter is out of sync", "Their password was changed at the same time"], answerIndex: 1, explanation: "TOTP depends on both sides agreeing on the time. A device clock that drifts (e.g. after travel or a time-zone change) produces codes the server computes differently — not a corrupted secret." },
    { id: "mfa-09", type: "concept", question: "What is the key property of a WebAuthn/FIDO2 private key that distinguishes it from a typed password or OTP code?", options: ["It changes every 30 seconds automatically", "It never leaves the device and is never seen or typed by the user", "It is shared between the device and server over an encrypted channel at every login", "It is identical across all of a user's registered devices"], answerIndex: 1, explanation: "The private key stays on the device (often in secure hardware); there is nothing the user types or copies, which removes the human-in-the-loop weakness that makes OTP codes phishable." },
    { id: "mfa-10", type: "scenario", question: "An attacker builds a convincing lookalike login page and captures a victim's password and OTP code, then immediately replays both against the real site. Why does an identical attack against a WebAuthn-protected login fail?", options: ["Because WebAuthn codes expire faster than OTP codes", "Because WebAuthn signatures are cryptographically bound to the real site's exact origin, so the lookalike site cannot obtain a usable signature at all", "Because WebAuthn requires a VPN connection", "Because WebAuthn disables itself automatically when phishing is detected"], answerIndex: 1, explanation: "The challenge-response signature is origin-bound. A different domain (the lookalike site) cannot produce or relay a signature that validates against the real site's origin." },
    { id: "mfa-11", type: "compare", question: "How does a passkey relate to WebAuthn and FIDO2?", options: ["A passkey is an entirely separate protocol unrelated to WebAuthn or FIDO2", "A passkey is the user-facing, syncable form of a FIDO2/WebAuthn credential", "WebAuthn is a type of passkey used only on mobile devices", "FIDO2 is a deprecated predecessor that passkeys replaced entirely"], answerIndex: 1, explanation: "Passkey is the consumer-facing branding for a FIDO2/WebAuthn credential, typically one that syncs across a user's devices via their platform account." },
    { id: "mfa-12", type: "concept", question: "What does 'phishing-resistant authentication' specifically mean, as defined in this chapter?", options: ["Any method that uses more than one factor", "A method whose proof cannot be captured and replayed from a fake site, because the proof itself has nothing a human can be tricked into typing or copying and is bound to the real origin", "Any method that requires biometrics", "A method that blocks known phishing domains via a blocklist"], answerIndex: 1, explanation: "Having multiple factors (MFA) is not the same as being phishing-resistant — a password plus a typed OTP code is still phishable, while origin-bound WebAuthn signatures are not." },
    { id: "mfa-13", type: "concept", question: "What is the defining difference between risk-based (adaptive) authentication and a flat 'always require MFA' policy?", options: ["Risk-based authentication never requires any additional factor", "Risk-based authentication raises or lowers the required proof based on contextual signals, instead of applying the same requirement to every login or action", "A flat policy is always more secure than a risk-based one", "Risk-based authentication only applies to administrator accounts"], answerIndex: 1, explanation: "Risk-based authentication varies the bar according to evaluated signals (device, location, action sensitivity) rather than treating every situation identically." },
    { id: "mfa-14", type: "scenario", question: "Meridian Trust's online banking customer logs in from their usual phone and transfers $20 to a payee they've paid monthly for two years — no extra prompt appears. The same customer then attempts a first-time $20,000 transfer from an unrecognized browser, and is challenged for an additional factor. What does this illustrate?", options: ["A flat MFA policy applied to every transaction equally", "Step-up authentication triggered by risk-based signals — the unusual amount, new payee context, and unfamiliar device raised the risk score for the second transaction", "A bug, since both transactions should require the same proof", "That Meridian Trust does not use MFA for routine transactions"], answerIndex: 1, explanation: "This is risk-based authentication in action: routine behavior passes with the normal factor set, while signals indicating elevated risk (new device, large amount, unusual payee) trigger step-up authentication specifically for the sensitive action." },
    { id: "mfa-15", type: "bug", question: "An application prompts every user for a fresh MFA code on every single click within the app, including harmless read-only actions. What is the most likely design flaw, per this chapter?", options: ["The application is using HOTP instead of TOTP", "A missing risk-based layer — treating all actions as equally sensitive instead of reserving step-up challenges for actions that actually warrant them", "The application does not support WebAuthn", "The application's shared secret was never rotated"], answerIndex: 1, explanation: "Constant re-prompting for low-sensitivity actions is a sign the system lacks risk-based differentiation, which also trains users to click through prompts without reading them — undermining the control's purpose." },
    { id: "mfa-16", type: "compare", question: "How does an Authenticator Assurance Level (AAL), per NIST SP 800-63B, relate to the factor categories discussed in this chapter?", options: ["AAL is a replacement term for 'factor category' with no additional meaning", "AAL is a tiered classification of how strong a combination of authentication factors is overall, used as a reference point for how much assurance a given requirement calls for", "AAL only applies to inherence factors", "AAL measures how fast an authentication method completes, not its strength"], answerIndex: 1, explanation: "AAL (AAL1-AAL3) classifies overall authentication strength based on the factors and implementation used, giving a standard reference point for how much assurance a given risk or compliance requirement needs." }
  ],

  "authorization-models": [
    { id: "azm-01", type: "concept", question: "What question does every one of the five authorization models (ACL, RBAC, ABAC, PBAC, ReBAC) ultimately answer?", options: ["Who is this subject, really?", "Can subject S perform action A on resource R?", "Has this subject's password expired?", "Which identity provider authenticated this subject?"], answerIndex: 1, explanation: "All five models are different structural answers to the same yes/no access question; they differ in where the decision logic lives, not in what question they answer." },
    { id: "azm-02", type: "concept", question: "In an Access Control List (ACL) model, where do permissions live?", options: ["Attached to a role that subjects are assigned to", "Computed from attributes at request time", "Attached directly to the resource, listing which subjects can do what", "Derived from a relationship graph"], answerIndex: 2, explanation: "ACLs attach permissions directly to the resource itself, per subject — the defining trait that also causes their N-resources-by-M-subjects scaling problem." },
    { id: "azm-03", type: "concept", question: "Why do ACLs scale poorly as an organization grows?", options: ["They require a graph database", "They roughly grow as N resources × M subjects of entries to maintain", "They cannot express read vs. write permissions", "They require every subject to have the same role"], answerIndex: 1, explanation: "Because every grant is listed explicitly per resource and per subject with no shared structure, the maintenance burden grows with both the resource count and the subject count." },
    { id: "azm-04", type: "concept", question: "What indirection does RBAC introduce that ACLs don't have?", options: ["Permissions attach to roles, and subjects are assigned to roles", "Permissions attach to a relationship graph", "Permissions are computed from environment attributes only", "Permissions require a policy engine to evaluate"], answerIndex: 0, explanation: "RBAC's defining feature is the role layer: permissions are defined once per role, and subjects are connected to roles, rather than permissions being listed per subject directly." },
    { id: "azm-05", type: "scenario", question: "Northwind Apps gives every customer tenant an \"admin\" role for managing that tenant's users and settings. What must be true for this to be safe in a multi-tenant product?", options: ["Every tenant must share the exact same admin account", "The role assignment must be scoped to that specific tenant, not just checked by role name", "The role must be renamed uniquely per tenant", "Tenant admins must also hold a global super-admin role"], answerIndex: 1, explanation: "A role name alone carries no scope. The permission check must verify the role applies to this specific tenant, or every tenant admin platform-wide would be able to administer every other tenant." },
    { id: "azm-06", type: "bug", question: "A SaaS platform's authorization code checks only `user.roles.includes(\"tenant-admin\")` before allowing a settings change, with no check of which tenant the request targets. What is the resulting bug?", options: ["The system will reject all legitimate admin requests", "Any tenant's admin can modify the settings of every other tenant on the platform", "The role check will always return false", "This is not a bug — RBAC doesn't support per-tenant scoping"], answerIndex: 1, explanation: "Without checking that the role applies to the specific tenant being accessed, the role check only confirms \"is an admin somewhere,\" letting any tenant admin reach every tenant's data — a classic missing-resource-scope RBAC bug." },
    { id: "azm-07", type: "concept", question: "What does an ABAC system use to compute an access decision?", options: ["A static per-resource list of subjects", "A pre-assigned role held by the subject", "Attributes of the subject, resource, and environment, evaluated at request time", "A fixed hierarchy of job titles"], answerIndex: 2, explanation: "ABAC decisions are computed live from attributes rather than looked up from a pre-assigned role or list, which is what lets it react to data that changes per request." },
    { id: "azm-08", type: "scenario", question: "At Meridian Trust, a teller's authorized wire-transfer ceiling depends on an account-risk attribute rather than the teller's job title alone. Which model does this best illustrate?", options: ["ACL, because each account has its own list of tellers", "RBAC, because the teller role determines the entire limit", "ABAC, because the decision is computed from an attribute of the resource (the account) combined with the subject", "ReBAC, because it depends on a care-team relationship"], answerIndex: 2, explanation: "The limit isn't fixed by the teller's role alone — it's computed from the account's risk attribute at decision time, which is the defining trait of ABAC." },
    { id: "azm-09", type: "bug", question: "An ABAC rule is intended to cap a teller's approval authority using the CURRENT account-risk attribute, but the application actually reads a cached risk score computed at login time and never refreshed during the session. What is the resulting problem?", options: ["The rule works exactly as intended", "A teller could approve a transfer based on a stale risk attribute that no longer reflects the account's real risk", "This turns the system into RBAC instead of ABAC", "The rule would simply fail to evaluate and deny everything"], answerIndex: 1, explanation: "ABAC's whole value is deciding from current attribute values; using a stale, session-cached value defeats that and can let a now-risky account get approvals based on an outdated, lower-risk snapshot." },
    { id: "azm-10", type: "compare", question: "What is the most honest way to describe the relationship between ABAC and PBAC?", options: ["They are unrelated, completely separate models with no overlap", "PBAC is strictly older and has been fully replaced by ABAC", "They overlap heavily — most PBAC systems evaluate policies over attributes, making PBAC often a way of implementing ABAC rather than a wholly separate model", "ABAC is only used for authentication, not authorization"], answerIndex: 2, explanation: "The literature and vendors don't draw a crisp line between the two; PBAC emphasizes how decision logic is packaged (as explicit policy), but that logic usually operates over attributes, so the two heavily overlap in practice." },
    { id: "azm-11", type: "concept", question: "What is a practical reason an organization might centralize ABAC-style checks into a dedicated policy engine (moving toward a PBAC approach)?", options: ["Policy engines eliminate the need for attributes entirely", "It lets policies be authored, versioned, and audited independently of the applications that enforce them", "It removes the need for any authentication step", "It converts the model into RBAC automatically"], answerIndex: 1, explanation: "Centralizing policy as its own governed artifact, separate from application code, is the main operational benefit — changes to policy don't require redeploying every consuming application." },
    { id: "azm-12", type: "concept", question: "What does a ReBAC model base its access decisions on?", options: ["A static list of permissions per resource", "Relationships between subjects and resources, modeled as a graph", "A fixed set of job-function roles", "Only attributes of the environment, such as time of day"], answerIndex: 1, explanation: "ReBAC's defining trait is evaluating relationships — edges in a graph, like \"owns\" or \"is on the care team for\" — rather than roles or attribute values alone." },
    { id: "azm-13", type: "scenario", question: "Riverside Health wants clinicians to access a patient's chart only if they're currently treating that patient, not just because they hold a \"clinician\" role somewhere in the hospital network. Which model fits this requirement best, and why?", options: ["RBAC, because \"clinician\" is already a role", "ABAC, because it only needs the clinician's department attribute", "ACL, because each chart can just list every clinician in the network", "ReBAC, because access should follow the specific, changing care-team relationship rather than a blanket role"], answerIndex: 3, explanation: "A flat \"clinician\" role would let every clinician in the network see every chart — a privacy and compliance problem. The correct scope is the specific, changing care-team relationship, which is what ReBAC is built to express." },
    { id: "azm-14", type: "compare", question: "Compared to RBAC, what is ReBAC's main scalability trade-off?", options: ["ReBAC always requires fewer infrastructure components than RBAC", "ReBAC fits relationship-driven access well, but requires maintaining an accurate, frequently changing relationship graph and evaluating graph traversals at request time", "ReBAC has no scalability trade-offs because it uses the same roles as RBAC", "ReBAC cannot express fine-grained access at all"], answerIndex: 1, explanation: "ReBAC's strength (precise, relationship-scoped access) comes with the cost of graph infrastructure: keeping relationships current and evaluating potentially multi-hop traversals, a different engineering problem than a role lookup." },
    { id: "azm-15", type: "concept", question: "Which statement best describes Zero Trust and least privilege in relation to the five authorization models?", options: ["They are a sixth authorization model, alternative to ACL/RBAC/ABAC/PBAC/ReBAC", "They are cross-cutting principles about how generous any of the five models' decisions should be, applicable regardless of which model is used", "They only apply to ReBAC systems", "They replace the need for authentication entirely"], answerIndex: 1, explanation: "Zero Trust (\"never trust, always verify\") and least privilege (grant only the minimum needed) are principles layered on top of whichever model is in use, not a model of their own." },
    { id: "azm-16", type: "compare", question: "Looking at the five-model comparison table, which model's typical scalability concern is described as 'grows as N resources × M subjects'?", options: ["RBAC", "ABAC", "ACL", "PBAC"], answerIndex: 2, explanation: "ACL is the model whose per-resource, per-subject listing structure directly produces this multiplicative scaling problem, unlike RBAC's role indirection or ABAC/PBAC's computed decisions." }
  ],

  "sso-and-federation": [
    { id: "sso-01", type: "concept", question: "SAML's 'Service Provider' and OIDC's 'Relying Party' refer to:", options: ["Two genuinely different roles in an SSO relationship", "The same role, named differently by two different protocol vocabularies", "The Service Provider only, with Relying Party being an OAuth-specific role", "A role that only exists in brokering, not federation"], answerIndex: 1, explanation: "SP (SAML) and RP (OIDC) both mean 'the application that trusts an external IdP's assertion instead of authenticating the user itself' — same role, different protocol vocabulary." },
    { id: "sso-02", type: "concept", question: "What does an Identity Provider (IdP) do in an SSO relationship?", options: ["Stores the relying application's business data", "Holds credentials, performs authentication, and asserts identity to another system", "Registers redirect URIs on behalf of the application", "Only applies to federation, not brokering"], answerIndex: 1, explanation: "The IdP is the system that authenticates the user and asserts the result; the relying application (SP/RP) trusts that assertion instead of authenticating directly." },
    { id: "sso-03", type: "scenario", question: "A user logs into Northwind Apps' dashboard, then later that day visits Northwind's separate billing portal, which is also configured to trust the same IdP. They are not asked to log in again. What made this possible?", options: ["Both apps store the same password hash", "The browser carries a session the shared IdP recognizes on the billing portal's redirect", "The billing portal silently reused the dashboard's local session cookie directly", "Northwind disabled authentication on the billing portal"], answerIndex: 1, explanation: "SSO works because the browser carries the IdP's session; a second app's redirect to the same IdP is recognized without re-authentication." },
    { id: "sso-04", type: "compare", question: "What is the key difference between identity brokering and identity federation?", options: ["Brokering is for SAML, federation is for OIDC", "Brokering delegates one login event to an external IdP; federation reuses an existing directory of accounts", "Federation is only used for customer-facing apps, brokering only for internal apps", "There is no meaningful difference — they are two names for the same pattern"], answerIndex: 1, explanation: "Brokering delegates authentication to an external IdP the user already has an account with; federation connects to an existing identity store/directory so its accounts can be reused." },
    { id: "sso-05", type: "scenario", question: "Riverside Health configures its Keycloak realm to check clinician logins directly against the hospital's existing Active Directory, rather than maintaining a second set of Keycloak-local passwords. This is an example of:", options: ["Identity brokering", "Identity federation", "JIT provisioning only, with no federation involved", "Social login"], answerIndex: 1, explanation: "Reusing an existing directory (AD) that the organization already runs, rather than delegating to an external IdP, is federation." },
    { id: "sso-06", type: "scenario", question: "Northwind Apps lets an enterprise customer's employees log in using the customer's own corporate IdP instead of a Northwind-issued password. In this relationship, Northwind is acting as the:", options: ["IdP, and the customer's system is the SP/RP", "SP/RP, trusting the customer's corporate IdP", "Directory being federated against", "Broker's external identity store"], answerIndex: 1, explanation: "Northwind's application relies on the customer's IdP's assertion instead of authenticating directly — Northwind is the SP/RP in this brokering relationship." },
    { id: "sso-07", type: "concept", question: "What is JIT (just-in-time) provisioning?", options: ["A scheduled nightly batch job that imports all directory accounts at once", "Automatically creating a local identity from external IdP/directory data on a user's first login", "A way to delete stale accounts automatically", "A SAML-only feature with no OIDC equivalent"], answerIndex: 1, explanation: "JIT provisioning creates the local identity automatically the first time a brokered or federated user logs in, instead of requiring manual pre-creation." },
    { id: "sso-08", type: "bug", question: "A support ticket says: 'A local account for an external user appeared in our system and nobody created it.' The user had just logged in for the first time via the company's brokered Google login. What is the most likely explanation?", options: ["A data breach created a fake account", "JIT provisioning created the account automatically on first successful login, as designed", "Someone bypassed the admin console", "The audit log is broken"], answerIndex: 1, explanation: "JIT provisioning silently creates a local account on first brokered/federated login — this is expected behavior, not a bug, though it can confuse a team unaware of it." },
    { id: "sso-09", type: "concept", question: "Which of the following is NOT one of the three ingredients of establishing trust between an IdP and an SP/RP?", options: ["Shared metadata describing endpoints and capabilities", "Certificates or signing keys to verify assertions", "Registered redirect URIs", "A shared database table storing both sides' user passwords"], answerIndex: 3, explanation: "Trust is built from metadata, certificates/signing keys, and registered redirect URIs — not a shared password store, which would defeat the point of not sharing credentials." },
    { id: "sso-10", type: "scenario", question: "Meridian Trust's mobile app redirects a customer to a login page, but the IdP refuses to send the login result back, citing an untrusted callback address. What is the most likely cause?", options: ["The customer's password was wrong", "The app's redirect URI was never registered with the IdP", "The IdP session expired mid-login", "Meridian disabled MFA"], answerIndex: 1, explanation: "IdPs only redirect to pre-registered redirect URIs as part of established trust; an unregistered one is rejected to prevent login results being hijacked elsewhere." },
    { id: "sso-11", type: "concept", question: "Why is 'everyone uses the same password' not the same thing as SSO?", options: ["Because SSO requires biometrics", "Because SSO means one authentication act is recognized across apps via a shared IdP session, not credential reuse", "Because password reuse is actually more secure", "Because SSO only works with social login"], answerIndex: 1, explanation: "True SSO is a shared-session handshake against one IdP; reusing the same password across independent apps is a weaker, insecure imitation with none of SSO's actual mechanics." },
    { id: "sso-12", type: "scenario", question: "A Northwind Apps engineer argues a new customer integration should 'federate' with the customer's Okta tenant so employees can use 'Login with Okta.' What pattern are they actually describing?", options: ["Federation, correctly described", "Brokering — delegating one login event to an external IdP, not reusing a directory", "User provisioning", "Service account creation"], answerIndex: 1, explanation: "'Login with X' where X authenticates the user and the app trusts the result is brokering, even though the word 'federate' is colloquially misused for it." },
    { id: "sso-13", type: "compare", question: "In an LDAP-federation setup, who remains the authoritative owner of the user's credential?", options: ["The IAM system doing the federating", "The external directory (e.g. Active Directory) being federated against", "Neither — the credential is discarded after first login", "The relying application (SP/RP)"], answerIndex: 1, explanation: "Federation reuses an existing directory; that directory remains the source of truth for the credential, checked via a bind operation rather than copied elsewhere." },
    { id: "sso-14", type: "scenario", question: "Riverside Health's clinicians are federated against hospital AD. Riverside now also wants to let clinicians who use personal Microsoft accounts sign in with those instead. What pattern does the new requirement call for?", options: ["Federation against Microsoft's directory", "Brokering — delegating that login to Microsoft as an external IdP", "The same federation configuration extended to cover Microsoft", "JIT provisioning is not applicable here"], answerIndex: 1, explanation: "Personal Microsoft accounts aren't an organization-owned directory to federate against — trusting Microsoft to authenticate the user is brokering, a different pattern and trust relationship than the AD federation." },
    { id: "sso-15", type: "concept", question: "Which statement best describes an 'assertion' in SSO/brokering/federation contexts?", options: ["A user's self-declared claim with no verification", "The message an IdP sends stating who the user is, after authenticating them", "A synonym for 'redirect URI'", "Only used in LDAP federation, never in brokering"], answerIndex: 1, explanation: "An assertion is the IdP's statement of identity (and often attributes) sent to the relying application after successful authentication — its exact format differs by protocol (SAML assertion vs. OIDC ID token) but the role is the same." },
    { id: "sso-16", type: "bug", question: "Two apps both trust the same Keycloak realm, but a user who is logged into App A still gets a full login prompt when visiting App B. Given SSO mechanics, what's a likely cause to investigate first?", options: ["App B's database is down", "The browser isn't carrying/sending the IdP's SSO session cookie to App B's redirect (e.g. cross-domain cookie issue), or App B isn't actually redirecting to the same IdP/realm", "The user's password expired", "JIT provisioning failed"], answerIndex: 1, explanation: "If both apps genuinely trust the same IdP, a forced re-login points to the SSO session not being recognized on the second redirect — often a cookie-scoping or misconfigured-realm issue, not a credential problem." }
  ],

  "tokens-and-sessions": [
    { id: "tok-01", type: "concept", question: "What is the defining property of a bearer token?", options: ["It can only be used from the IP address it was issued to", "Whoever holds and presents it can use it, with no proof they are the party it was issued to", "It automatically expires the moment it is copied", "It requires a second factor every time it is presented"], answerIndex: 1, explanation: "\"Bearer\" means possession is the only thing checked — the token itself carries no proof that the presenter is its original owner." },
    { id: "tok-02", type: "concept", question: "What is a claim, in the conceptual sense this chapter introduces?", options: ["The raw cryptographic signature bytes of a token", "A key-value assertion inside a token that the issuer is vouching for, such as who it's for or when it expires", "A support ticket filed when a token stops working", "The network protocol used to transmit the token"], answerIndex: 1, explanation: "Claims are the statements carried inside a token (subject, issuer, expiry, authorization data, audience); the exact wire format is chapter 16's job." },
    { id: "tok-03", type: "compare", question: "How do stateless and stateful authentication architectures differ in how a server checks a request?", options: ["Stateless requires a server-side lookup; stateful needs none", "Stateless verifies a self-contained token with no database lookup; stateful looks a session identifier up against a shared store", "They are identical in cost and revocability", "Stateful is always faster because it never touches a database"], answerIndex: 1, explanation: "Stateless tokens are self-verifying; stateful sessions require consulting a shared, server-side session store on every request." },
    { id: "tok-04", type: "scenario", question: "Meridian Trust deliberately issues very short-lived access tokens for its banking API. What is this directly a response to?", options: ["A limitation of its database hardware", "The revocation problem — it can't cleanly revoke a stolen stateless token early, so it shrinks the window a stolen token stays useful", "A regulatory requirement that tokens must be human-readable", "A preference for fewer total API calls per day"], answerIndex: 1, explanation: "Since Meridian can't revoke a plain stateless bearer token early, shrinking its lifetime is the direct mitigation it chooses given PCI-DSS and fraud exposure." },
    { id: "tok-05", type: "scenario", question: "Northwind Apps wants customers to stay logged in for weeks without re-entering credentials. What trade-off does this force onto its refresh-token lifetime decision?", options: ["No trade-off exists — longer refresh tokens are strictly better", "User convenience (staying logged in longer) against greater exposure if a stolen refresh token stays usable for that same longer window", "Refresh tokens have no effect on login duration", "The trade-off only matters for access tokens, not refresh tokens"], answerIndex: 1, explanation: "A longer-lived refresh token means more convenience but a longer usable window for a thief who steals one — there's no setting that gives both for free." },
    { id: "tok-06", type: "concept", question: "Why can't a stateless bearer token be cleanly revoked early, in the general case?", options: ["Because tokens are legally required to remain valid until expiry", "Because adding a central early-revocation check reintroduces the server-side lookup that statelessness exists to avoid", "Because revocation is a solved problem that all systems already implement correctly", "Because tokens are encrypted and therefore cannot be inspected"], answerIndex: 1, explanation: "The moment you add a revocation check, you've reintroduced the stateful lookup — it's a structural consequence of choosing statelessness, not a missing feature." },
    { id: "tok-07", type: "bug", question: "An incident-response runbook says: \"If an access token is compromised, revoke it immediately from the admin console.\" The system issues plain, short-lived stateless bearer tokens with no introspection endpoint. What is the actual outcome when this step is attempted during a real incident?", options: ["It works exactly as written, instantly invalidating the token everywhere", "There may be no mechanism to revoke that specific already-issued token at all — the team discovers the honest answer is \"wait for it to expire\"", "The token automatically re-issues itself with new claims", "Revoking it also revokes every other user's token as a side effect"], answerIndex: 1, explanation: "This is the exact pitfall the chapter calls out: a plain stateless design may have no way to revoke one specific token early, and teams that assumed otherwise get burned mid-incident." },
    { id: "tok-08", type: "bug", question: "A team adds a central revocation-check step so every server calls a shared service before honoring any token, then is confused that their system no longer scales the way their original stateless design promised. What is the cause?", options: ["Their database hardware degraded over time", "The revocation check reintroduced the exact server-side lookup that statelessness was chosen specifically to avoid, turning the system stateful in practice", "They forgot to enable caching on their load balancer", "Tokens became larger after the change, slowing parsing"], answerIndex: 1, explanation: "Adding any central \"is this still valid\" check converts a stateless system into a stateful one in all but name — the scaling benefit that motivated statelessness is gone." },
    { id: "tok-09", type: "concept", question: "What does token introspection let a resource server do, and what does it cost?", options: ["Rewrite a token's claims locally with no issuer involvement, at no cost", "Call back to the issuer on each request to ask whether a token is still valid, at the cost of reintroducing a server-side lookup", "Decrypt any token without a key, at no cost", "Permanently disable all tokens system-wide, at the cost of an outage"], answerIndex: 1, explanation: "Introspection (full mechanics in chapter 14) works, but it trades back part of the stateless benefit by requiring a real-time check against the issuer." },
    { id: "tok-10", type: "concept", question: "Why is signing-key rotation described as a \"blunt\" mitigation for the revocation problem?", options: ["It only works for refresh tokens, never access tokens", "It invalidates every token signed with the old key at once, rather than targeting one specific token", "It requires the attacker's cooperation to take effect", "It has no effect on any already-issued token"], answerIndex: 1, explanation: "Rotating the signing key invalidates everything signed with the old key — effective after a suspected key compromise, but not a way to revoke one token selectively. Full depth in chapter 16." },
    { id: "tok-11", type: "scenario", question: "An attacker intercepts a copy of a customer's valid access token and presents it to the same API the customer uses. What does the API see?", options: ["A request it correctly flags as fraudulent because tokens carry an owner's fingerprint", "A request indistinguishable from the real customer's, because possession of the token is the only thing being checked", "An automatic rejection, because bearer tokens can only be used once", "A request that is silently ignored"], answerIndex: 1, explanation: "Bearer tokens carry no proof of who is presenting them — the API cannot tell the attacker's request apart from the legitimate owner's." },
    { id: "tok-12", type: "compare", question: "What is the key structural difference between what a client holds under a token-based scheme versus a session-based scheme?", options: ["A token is always encrypted; a session identifier is always plaintext", "A token is self-contained data describing the subject; a session identifier is opaque and means nothing without a server-side lookup", "There is no structural difference, only a naming difference", "A session identifier always contains more claims than a token"], answerIndex: 1, explanation: "A token carries its own verifiable content; a session identifier is just a pointer into a server-side record." },
    { id: "tok-13", type: "concept", question: "What does refresh-token rotation actually mitigate, and what does it NOT do?", options: ["It eliminates the revocation problem entirely for all tokens", "It limits how long a stolen refresh token stays useful by keeping access tokens short-lived, but it does not make a stolen access token instantly revocable", "It makes every token permanently valid", "It removes the need for any token expiry at all"], answerIndex: 1, explanation: "Rotation narrows the exposure window by moving trust checks to the refresh step; it's a partial mitigation, not a full fix for the underlying revocation problem." },
    { id: "tok-14", type: "scenario", question: "A product team is deciding how long a refresh token should live for a consumer SaaS app. Which question best reflects the trade-off this chapter describes?", options: ["Should we skip refresh tokens entirely and only use passwords?", "How much convenience (staying logged in longer) are we willing to trade against how much exposure a stolen refresh token would create for that same duration?", "Should refresh tokens be stored in plaintext for easier debugging?", "Does the refresh token need to contain the user's password?"], answerIndex: 1, explanation: "This is exactly Northwind's dilemma: refresh-token lifetime is a direct trade between user convenience and security exposure, with no setting that avoids the trade entirely." },
    { id: "tok-15", type: "concept", question: "Which claim category answers \"which service is this token meant to be used against\"?", options: ["Issuer", "Audience", "Validity window", "Subject"], answerIndex: 1, explanation: "The audience claim identifies the intended recipient service, preventing a token issued for one API from being silently reused against another." },
    { id: "tok-16", type: "bug", question: "A support engineer insists \"the token proves it was really her\" after a disputed transaction traced to a valid access token. What is the flaw in that reasoning?", options: ["There is no flaw — token validity always proves principal identity", "A bearer token only proves someone possessed it; it does not prove the presenter is the principal it was originally issued to", "Tokens cannot be used to trace transactions at all", "The flaw is that tokens never contain a subject claim"], answerIndex: 1, explanation: "This is the core pitfall: conflating bearer-token possession with principal identity. A stolen token says exactly the same thing a legitimate one does." },
    { id: "tok-17", type: "compare", question: "How do short token lifetimes and token introspection differ as mitigations for the revocation problem?", options: ["Short lifetimes shrink the exposure window passively without a lookup; introspection actively checks validity on each request but reintroduces a server-side lookup", "They are functionally identical mitigations", "Short lifetimes require a database; introspection never does", "Introspection eliminates the need for token expiry entirely"], answerIndex: 0, explanation: "Short lifetimes work without adding any lookup cost, just a smaller window; introspection adds real-time control at the cost of the lookup statelessness was meant to avoid." },
    { id: "tok-18", type: "concept", question: "What must a stateful authentication architecture provide that a stateless one does not need?", options: ["A signing key", "A shared session store reachable by every server handling requests", "A refresh token", "An audience claim"], answerIndex: 1, explanation: "Stateful designs require a shared, server-side session store every server can reach; stateless designs need no such shared infrastructure." }
  ],

  "iam-threat-landscape": [
    { id: "thr-01", type: "concept", question: "What makes credential stuffing effective, even though the attacker never guesses or cracks a password?", options: ["The attacker uses real username/password pairs leaked from an unrelated site's breach, betting on password reuse", "The attacker exploits a flaw in the hashing algorithm used to store passwords", "The attacker intercepts passwords in transit over an unencrypted connection", "The attacker brute-forces a single account with a dictionary of common passwords"], answerIndex: 0, explanation: "Credential stuffing relies entirely on password reuse across sites; the credentials being tried are already valid somewhere, just not necessarily at the target." },
    { id: "thr-02", type: "scenario", question: "Meridian Trust sees hundreds of thousands of failed logins over a weekend, each IP trying exactly one username/password pair before moving on, and the credentials match an unrelated retail site's breach dump. What is this attack, and why does it succeed for some accounts despite Meridian's passwords never being compromised?", options: ["Credential stuffing; it succeeds for customers who reused their retail-site password on their banking account", "Brute-force attack; it succeeds because Meridian's password policy was too weak", "Session hijacking; it succeeds because Meridian's session cookies weren't marked HttpOnly", "Token replay; it succeeds because Meridian's access tokens never expire"], answerIndex: 0, explanation: "The one-attempt-per-IP, known-credential pattern is the signature of credential stuffing; it only succeeds against customers who reused a password Meridian never stored or leaked." },
    { id: "thr-03", type: "scenario", question: "After the credential-stuffing wave, Meridian adds a CAPTCHA to the login form, but a measurable number of attacks still succeed because the submitted passwords are genuinely correct for those accounts. What should Meridian add next to stop a correct-password-but-wrong-person login from succeeding?", options: ["A second authentication factor (MFA), since a CAPTCHA only slows automation, it doesn't verify the real account owner", "A longer minimum password length requirement", "Encrypting passwords at rest instead of hashing them", "Moving the login form to a different URL"], answerIndex: 0, explanation: "CAPTCHA defends against automation, not against a correct-but-stolen password; MFA is what verifies the attempt actually comes from the legitimate account owner." },
    { id: "thr-04", type: "concept", question: "What distinguishes phishing from credential stuffing as an attack on authentication?", options: ["Phishing manufactures a brand-new credential disclosure directly from the victim; credential stuffing reuses credentials already leaked elsewhere", "Phishing only works against API clients, not browser-based logins", "Phishing requires the attacker to already have network access to the victim's organization", "Phishing is a defense technique, not an attack technique"], answerIndex: 0, explanation: "Credential stuffing bets on reuse of already-breached credentials; phishing actively tricks the victim into disclosing a credential for the first time, regardless of reuse." },
    { id: "thr-05", type: "scenario", question: "Riverside Health clinicians receive an email impersonating the hospital IT help desk, linking to a pixel-perfect copy of the real SSO login page on a lookalike domain. What makes this attack effective against busy clinicians specifically?", options: ["A believable urgent pretext (account lockout) combined with a convincing fake page, exploiting trust and time pressure rather than any system flaw", "A flaw in the hospital's Active Directory password hashing", "The hospital's SSO system failing to issue tokens correctly", "A brute-force attack against the clinicians' MFA codes"], answerIndex: 0, explanation: "Phishing exploits human trust and urgency, not a technical flaw in the real system — the fake page and pretext are the entire attack." },
    { id: "thr-06", type: "scenario", question: "A Meridian Trust employee's credentials are phished through an adversary-in-the-middle (AiTM) proxy that relays their OTP code to the real service in real time, giving the attacker a live session. Which MFA approach would have resisted this specific technique, and why?", options: ["WebAuthn/passkeys, because they're bound to the real site's origin and can't be relayed through a lookalike proxy domain", "SMS-based OTP, because text messages can't be intercepted", "A longer OTP code, because longer codes are harder to relay", "Security questions, because they aren't tied to a specific login page"], answerIndex: 0, explanation: "AiTM phishing works by relaying whatever the victim enters, including OTP codes. WebAuthn/passkeys are origin-bound, so a credential registered for the real site simply won't authenticate against the attacker's proxy domain." },
    { id: "thr-07", type: "scenario", question: "Northwind Apps learns that an enterprise customer's own browser-based integration has an XSS flaw — code Northwind didn't write — and an attacker used it to read a Northwind-issued bearer token out of that customer's browser storage. Whose design choice determines how much damage results from this XSS bug?", options: ["Northwind's, because the token's scope and lifetime it chose determine the attacker's blast radius and window, regardless of whose code had the bug", "The customer's alone, because the vulnerable code is entirely theirs", "Neither party's, because XSS attacks can't be mitigated by token design", "The browser vendor's, because XSS is a browser-level flaw"], answerIndex: 0, explanation: "The XSS bug is the customer's, but Northwind's own choice of how long-lived and broadly-scoped the token is determines how much an attacker can do with it once stolen — that's the provider's design decision, not the customer's." },
    { id: "thr-08", type: "scenario", question: "What broader lesson does Northwind Apps' incident illustrate about being a SaaS provider?", options: ["A SaaS provider can inherit real risk from vulnerabilities in a customer's own integration code it doesn't control, and its own token design determines how much that risk costs", "SaaS providers are never responsible for incidents that originate in customer-side code", "Multi-tenant SaaS platforms are immune to token theft because tenants are isolated", "The only way to prevent this kind of incident is to ban customers from writing their own integrations"], answerIndex: 0, explanation: "The scenario is specifically chosen to show that a provider's blast radius extends into customer-side code it can't control, and that scoping/lifetime choices are the provider's real lever for containing that risk." },
    { id: "thr-09", type: "compare", question: "How does token replay differ from token theft?", options: ["Token theft is the act of stealing the token; token replay is the subsequent act of reusing the stolen token to authenticate again before it expires", "Token theft only applies to SAML assertions; token replay only applies to OAuth tokens", "Token replay happens before theft, and theft happens after", "They are the same attack described with two different names for the same single step"], answerIndex: 0, explanation: "Theft is acquiring the token; replay is what the attacker does with it afterward — reusing it as if they were the legitimate holder." },
    { id: "thr-10", type: "concept", question: "What is session hijacking?", options: ["Stealing a session identifier or cookie to impersonate an already-authenticated session", "Sending repeated MFA push notifications until one is approved", "Using breached credentials from another site against a login form", "Tricking a user into disclosing their password via a fake login page"], answerIndex: 0, explanation: "Session hijacking targets the session identifier itself, not the credential or token that created it." },
    { id: "thr-11", type: "compare", question: "What is the key mechanical difference between session hijacking and token theft, even though both produce the same outcome (impersonating the user)?", options: ["Session hijacking steals a server-side-looked-up identifier (a cookie); token theft steals a self-contained bearer credential", "Session hijacking only affects mobile apps; token theft only affects web browsers", "Session hijacking requires physical access to the victim's device; token theft never does", "There is no mechanical difference — they are the same attack under two names"], answerIndex: 0, explanation: "A session cookie is typically an opaque reference the server looks up; a bearer token is self-contained proof. Different mechanics, same consequence: whoever holds either one is treated as the user." },
    { id: "thr-12", type: "concept", question: "What does MFA fatigue (push bombing) require the attacker to already possess before it can work?", options: ["A valid password for the target account — the push bombing is how they get past the second factor, not the first", "Physical access to the victim's phone", "A copy of the target's biometric data", "Administrative access to the identity provider"], answerIndex: 0, explanation: "Push bombing only makes sense once the attacker already has a correct password; the technique exists specifically to get past MFA once the first factor is already compromised." },
    { id: "thr-13", type: "scenario", question: "A Meridian Trust employee receives five MFA push notifications between 23:58 and 00:04, well outside normal login hours, and approves the fifth one assuming it's a glitch. What attack is this, and what single system-level change would have prevented the approval regardless of the employee's tiredness?", options: ["MFA fatigue / push bombing; switching to a phishing-resistant factor with no approve/deny prompt to fatigue, such as WebAuthn, removes the option to mistakenly approve", "Credential stuffing; adding a CAPTCHA to the push notification screen", "Session hijacking; shortening the session cookie's lifetime", "Token replay; rotating the signing key used to issue tokens"], answerIndex: 0, explanation: "The repeated-push, eventual-approval pattern is push bombing. A factor like WebAuthn has no notification to repeatedly send and approve, which removes the attack's mechanism entirely rather than relying on the user staying vigilant." },
    { id: "thr-14", type: "bug", question: "A login endpoint accepts unlimited login attempts per account with no delay, lockout, or CAPTCHA. Which attack does this specifically enable at scale, and why?", options: ["Credential stuffing, because an attacker can fire millions of breached username/password pairs at the endpoint without ever being slowed down or blocked", "Phishing, because the missing rate limit makes the fake login page more convincing", "Session hijacking, because unlimited attempts let an attacker guess a session cookie", "MFA fatigue, because unlimited attempts let an attacker send unlimited push notifications"], answerIndex: 0, explanation: "Missing rate limiting / lockout is precisely what lets credential stuffing operate at the scale needed for even a tiny reuse rate to produce many account takeovers; chapter 30 covers configuring exactly this control in Keycloak." },
    { id: "thr-15", type: "bug", question: "A system logs only successful logins and discards failed-login attempts entirely. What does this specifically prevent the security team from detecting?", options: ["An ongoing credential-stuffing or brute-force campaign, since the pattern of many failed attempts is the main early signal that one is underway", "Successful account takeovers, since those are logged as successful logins either way", "Phishing emails arriving in employee inboxes", "Token theft via a client-side XSS vulnerability"], answerIndex: 0, explanation: "Credential stuffing and brute-force attacks are visible primarily through volume and patterns of failed attempts; discarding that data blinds the team to the attack while it's still in progress, not just after it succeeds." },
    { id: "thr-16", type: "scenario", question: "Riverside Health's security lead, after the clinician phishing incident, asks which later chapter in this course covers the authentication factor that would have resisted it. Which chapter, and which factor?", options: ["Chapter 5, which covers WebAuthn/passkeys as phishing-resistant, origin-bound authentication", "Chapter 10, which covers joiner-mover-leaver provisioning", "Chapter 17, which covers SAML assertions and bindings", "Chapter 27, which covers the Keycloak Admin REST API"], answerIndex: 0, explanation: "Chapter 5 introduces WebAuthn/FIDO2/passkeys specifically as the phishing-resistant authentication factor category that AiTM-style phishing can't relay." },
    { id: "thr-17", type: "scenario", question: "Northwind Apps' engineering lead asks which later chapter covers hardening token issuance and storage against the kind of theft Northwind experienced. Which chapter?", options: ["Chapter 18, which covers OAuth/OIDC security best current practice, including safe token storage and sender-constrained tokens", "Chapter 11, which covers compliance frameworks like GDPR and HIPAA", "Chapter 32, which covers LDAP and Active Directory user federation", "Chapter 4, which covers directory services and identity stores"], answerIndex: 0, explanation: "Chapter 18 is where this course covers the OAuth 2.0 Security Best Current Practice guidance (token storage pitfalls, sender-constrained tokens) that directly answers token theft." },
    { id: "thr-18", type: "scenario", question: "Meridian Trust's compliance team asks which later chapter covers the Keycloak-specific control that would have slowed down its credential-stuffing wave automatically, without waiting for a human to notice the spike. Which chapter?", options: ["Chapter 30, which covers password policies, brute-force protection, and MFA configuration in Keycloak", "Chapter 21, which covers realms and realm settings", "Chapter 37, which covers Keycloak Authorization Services (UMA 2.0)", "Chapter 13, which covers OAuth 2.0 grant types"], answerIndex: 0, explanation: "Chapter 30 is where this course configures Keycloak's realm-level brute-force detection — the automated lockout/delay mechanism that answers credential stuffing without manual intervention." }
  ],

  "identity-governance": [
    { id: "iga-01", type: "concept", question: "What does IGA (Identity Governance & Administration) primarily refer to, as this course uses the term?", options: ["A specific vendor product category like SailPoint or Saviynt", "The discipline of provisioning, reviewing, and governing access over an identity's entire lifetime", "A synonym for single sign-on", "The encryption method used to protect access tokens"], answerIndex: 1, explanation: "IGA is the process discipline — granting, reviewing, and governing access over time. The tooling market category that automates it is a separate subject covered in chapter 12." },
    { id: "iga-02", type: "concept", question: "Joiner-Mover-Leaver (JML) maps onto which lifecycle stages from chapter 2?", options: ["It replaces chapter 2's lifecycle with a new five-stage model", "Joiner = create+activate, Mover = modify, Leaver = suspend+delete", "Joiner = modify, Mover = create+activate, Leaver = delete only", "JML has no relationship to chapter 2's lifecycle"], answerIndex: 1, explanation: "JML is HR vocabulary laid on top of the same create/activate/modify/suspend/delete stages, not a new or competing lifecycle model." },
    { id: "iga-03", type: "scenario", question: "Northwind Apps moves Priya from the support team to the platform engineering team. The system grants her the platform engineering role but leaves her existing support-team role untouched. What is the problem?", options: ["There is no problem — Mover events should only add access", "This is a correctly handled Mover event", "This treats Mover as purely additive, leaving stale, no-longer-justified access from her old role", "Priya should have been deleted and recreated instead"], answerIndex: 2, explanation: "A Mover event should remove access tied to the old role, not just add access for the new one. Leaving the old role in place is the classic Mover-trap mistake." },
    { id: "iga-04", type: "bug", question: "An access review at Northwind Apps finds several staff members hold role-scoped access from two or three teams they've rotated through over the years, with no single event ever having removed any of it. What caused this?", options: ["A bug in the authentication protocol", "Deprovisioning events were never configured", "Role-change (Mover) events were implemented as additive-only, never removing prior access", "The organization has too many case-study orgs"], answerIndex: 2, explanation: "This is the textbook Mover-trap pattern: access accumulates because role changes only grant, never revoke, the previous role's access." },
    { id: "iga-05", type: "concept", question: "What specifically makes a combination of permissions \"toxic\" under Segregation of Duties?", options: ["Either permission alone is dangerous", "The two permissions are rarely used together", "One identity holding both the ability to perform an action and the sole check on that same action", "The permissions span two different systems"], answerIndex: 2, explanation: "A toxic combination is defined precisely: the ability to both perform an action and be the only check on it. Neither permission needs to be dangerous in isolation." },
    { id: "iga-06", type: "scenario", question: "A Meridian Trust teller can both create a wire transfer request and approve it. What kind of problem is this?", options: ["A performance optimization, since one person can complete the task faster", "A toxic combination — Segregation of Duties is violated because the same identity both performs and checks the same action", "Not a problem as long as the teller is trustworthy", "An authentication (AuthN) issue, not an authorization (AuthZ) issue"], answerIndex: 1, explanation: "This is the canonical SoD violation: the teller could originate a fraudulent transfer and approve it themselves with no independent check." },
    { id: "iga-07", type: "scenario", question: "Riverside Health runs periodic access certification campaigns over clinician EHR access. Which compliance concept does this operationally support?", options: ["PCI-DSS cardholder data isolation", "GDPR's right to erasure", "HIPAA's minimum necessary standard — limiting access to what's currently needed", "SOC 2's availability trust service criterion"], answerIndex: 2, explanation: "Recurring certification is the mechanism that makes HIPAA's 'minimum necessary' standard demonstrable rather than just asserted, since chart access tends to outlive the clinical reason for it." },
    { id: "iga-08", type: "concept", question: "Why can't event-driven provisioning and deprovisioning alone keep an identity's access correct over time?", options: ["Because provisioning and deprovisioning are deprecated concepts", "Because they only react to events someone remembered to trigger — they can't catch access that accumulated without any triggering event", "Because Keycloak doesn't support provisioning events", "Because access reviews are required by law in every jurisdiction"], answerIndex: 1, explanation: "Stale access, by definition, has no triggering event pointing at it — only a deliberate, scheduled access review looks for it anyway." },
    { id: "iga-09", type: "compare", question: "How do an access review, an access certification, and attestation relate to each other?", options: ["They are three unrelated controls with no connection", "A review is the overall periodic exercise; a certification is the act of judging one entitlement within it; attestation is the reviewer's formally recorded confirmation", "Attestation happens before the review; certification happens after", "Certification is a synonym for deprovisioning"], answerIndex: 1, explanation: "Review is the umbrella activity, certification is the per-entitlement decision inside it, and attestation is the recorded proof that the decision was made." },
    { id: "iga-10", type: "bug", question: "A manager clicks \"certify all\" on a list of forty entitlements for twelve direct reports in under two minutes, and the campaign record shows it completed on schedule. What is wrong here?", options: ["Nothing — the campaign record proves compliance", "This is rubber-stamping: the record looks like a real review but no entitlement was actually evaluated, providing none of the review's security value", "The manager should have used a different Keycloak role", "This is a correct and efficient use of a recertification campaign"], answerIndex: 1, explanation: "A review's value comes entirely from the judgment applied, not from the existence of a dated record — rubber-stamping produces the record without the judgment." },
    { id: "iga-11", type: "concept", question: "What is \"stale access\"?", options: ["Access that was never granted correctly in the first place", "Access an identity still holds but no longer has a legitimate business reason to hold", "A session token that has expired", "A role with no permissions attached"], answerIndex: 1, explanation: "Stale access is specifically about access that was once legitimate but has outlived its justification — the thing access reviews are designed to find." },
    { id: "iga-12", type: "scenario", question: "At Meridian Trust, \"can approve wire transfers up to $5,000\" is reviewed as one specific grant during a recertification campaign, separately from everything else the teller can do. What is this specific grant called?", options: ["An attestation", "An entitlement", "A toxic combination", "A compensating control"], answerIndex: 1, explanation: "An entitlement is a single, specific grant — reviewed on its own merits rather than as part of an undifferentiated bundle of everything the identity can do." },
    { id: "iga-13", type: "compare", question: "Why is it accurate to say Keycloak is an IAM product but not an IGA product?", options: ["Because Keycloak is open source and IGA products are always commercial", "Because Keycloak enforces whatever access is configured but has no built-in feature for periodic access review, recertification campaigns, or SoD-conflict detection", "Because Keycloak doesn't support roles or groups at all", "Because IGA products don't support authentication"], answerIndex: 1, explanation: "Keycloak authenticates and enforces configured authorization, but it has no native mechanism asking whether previously-granted access is still justified — that's a genuine product-category distinction, not a missing feature to apologize for." },
    { id: "iga-14", type: "scenario", question: "Four months after an employee leaves Northwind Apps, an access review discovers their account is still active with its original permissions. What is this an example of?", options: ["A toxic combination", "An orphaned account — a missed Leaver trigger that deprovisioning never caught, found instead by the periodic review backstop", "A correctly functioning Joiner event", "An access certification"], answerIndex: 1, explanation: "An orphaned account results from a missing trigger for an existing deprovisioning process, not usually a missing process — exactly what periodic review exists to catch as a backstop." },
    { id: "iga-15", type: "concept", question: "What is the \"four-eyes principle\" (dual control)?", options: ["A requirement that every system have four administrators", "A sensitive action requires two different people — one to perform it, one to independently verify it — before it takes effect", "A biometric authentication factor using both eyes", "A rule that applies only to banking systems"], answerIndex: 1, explanation: "Four-eyes / dual control is the principle underlying SoD: two different people must be involved before a sensitive action takes effect." },
    { id: "iga-16", type: "scenario", question: "A two-person back office at Meridian Trust cannot fully separate the duties of creating and approving a transaction because there's no third person available. What is the appropriate response?", options: ["Ignore the conflict since the team is small", "Document an explicit compensating control, such as a mandatory secondary review by someone outside the team or an automatic flag on self-approved transactions", "Disable approval requirements entirely for this team", "Merge the two roles permanently since separation is impossible"], answerIndex: 1, explanation: "When true separation isn't feasible, the honest response is an explicit, documented compensating control — not a silent, unacknowledged gap." },
    { id: "iga-17", type: "compare", question: "How does a Joiner event differ from a Mover event in terms of what makes it error-prone?", options: ["Joiner events are harder because they require deleting old access", "Joiner events mostly need correct initial grants; Mover events are more error-prone because they require removing old access as well as adding new access, which is easy to skip", "Mover events never involve any access changes", "There is no meaningful difference between the two"], answerIndex: 1, explanation: "Joiner is largely a clean-slate grant. Mover is riskier precisely because it requires both an addition and a removal, and the removal half is the part beginners tend to skip." }
  ],

  "compliance-for-iam": [
    { id: "cmp-01", type: "concept", question: "What is this chapter's central argument about compliance frameworks and IAM?", options: ["Each framework defines a wholly new body of access-control theory that IAM specialists must learn separately", "Compliance frameworks largely restate the same underlying IAM fundamentals (authentication, authorization, accounting, data handling) under their own names and numbering", "Compliance frameworks are legally binding supersets of IAM theory that override earlier course concepts", "IAM concepts and compliance requirements are unrelated; compliance is a legal subject, IAM is a technical one"], answerIndex: 1, explanation: "The chapter's central claim is that GDPR, SOC 2, HIPAA, PCI-DSS, and ISO 27001 each independently converge on the same small set of IAM fundamentals under different vocabulary." },
    { id: "cmp-02", type: "scenario", question: "A Northwind Apps customer's employee emails asking what personal data Northwind holds about them and requests a copy in a machine-readable format. Which GDPR concept(s) is this request invoking?", options: ["Right to erasure only", "Data subject rights of access and portability (Articles 15 and 20)", "Lawful basis for processing only", "Data minimization"], answerIndex: 1, explanation: "A request to see and export personal data invokes the rights of access (Art. 15) and portability (Art. 20), not erasure." },
    { id: "cmp-03", type: "scenario", question: "A former Northwind customer employee invokes their GDPR right to erasure. Northwind's engineering team wants to also scrub every mention of that person from the access/audit logs used for security investigations. What does this chapter suggest they consider instead of full deletion of the logs?", options: ["Deleting all audit log entries referencing the person, since erasure requests override every other obligation", "Retaining the audit log entries but pseudonymizing the identifying fields, with legal sign-off, to balance erasure rights against audit-trail retention needs", "Ignoring the erasure request entirely because audit trails always take priority", "Moving the audit logs to a different jurisdiction to avoid GDPR scope"], answerIndex: 1, explanation: "Pseudonymizing (not deleting) log entries is the commonly used compromise, though it requires legal sign-off and isn't a universal clean answer." },
    { id: "cmp-04", type: "scenario", question: "An engineer at a SaaS company responds to a GDPR erasure request by writing a script that deletes every row in the audit log table referencing the requesting user's ID, including login and permission-change events from years prior. What is the risk in this approach?", options: ["None — this is exactly what GDPR erasure requires", "It may destroy evidence other frameworks (SOC 2, PCI-DSS Requirement 10) require retaining, and pseudonymization usually serves both obligations better", "GDPR erasure requests cannot legally be honored at all, so the script should never have run", "Audit logs are never considered personal data under GDPR, so this step was unnecessary"], answerIndex: 1, explanation: "Full deletion of audit records can conflict with other frameworks' retention requirements; pseudonymizing identifying fields is the better-reasoned middle ground." },
    { id: "cmp-05", type: "concept", question: "SOC 2 reports can cover up to five Trust Services Criteria categories. Which one is required in every SOC 2 report?", options: ["Privacy", "Availability", "Security", "Processing Integrity"], answerIndex: 2, explanation: "Security is the only Trust Services Criteria category mandatory in every SOC 2 report." },
    { id: "cmp-06", type: "scenario", question: "Meridian Trust is legally required to comply with PCI-DSS because it processes card payments. Why might Meridian also pursue a SOC 2 report even though no law mandates it?", options: ["SOC 2 legally supersedes PCI-DSS for banks", "Enterprise banking partners and fintech integrators commonly require a clean SOC 2 report before signing a contract, making it a commercial rather than legal necessity", "SOC 2 is required for any company with more than 50 employees", "PCI-DSS compliance automatically satisfies SOC 2 requirements, so pursuing both is redundant"], answerIndex: 1, explanation: "SOC 2 is frequently a commercial requirement (B2B partners demand it) layered on top of a separate legal requirement like PCI-DSS." },
    { id: "cmp-07", type: "scenario", question: "Meridian Trust is primarily scoped to PCI-DSS and SOC 2 in this course's case studies. What additional compliance exposure should a specialist check for before assuming that's the complete list?", options: ["None — banks are automatically exempt from every other framework", "Whether Meridian has any EU-based retail customers or staff, which would bring GDPR obligations into scope as well", "Whether Meridian has ever been audited before, which determines all future scope", "HIPAA, since all financial institutions are covered entities"], answerIndex: 1, explanation: "Real organizations often carry overlapping obligations; EU customer or staff exposure would bring GDPR into scope regardless of industry." },
    { id: "cmp-08", type: "concept", question: "The HIPAA Security Rule organizes its requirements into three categories of safeguards. What are they?", options: ["Preventive, detective, and corrective", "Administrative, physical, and technical", "Strategic, tactical, and operational", "Confidentiality, integrity, and availability"], answerIndex: 1, explanation: "The HIPAA Security Rule's three safeguard categories are administrative, physical, and technical." },
    { id: "cmp-09", type: "bug", question: "A compliance document states: \"Per the HIPAA Security Rule, covered entities must apply the minimum necessary standard to all ePHI access.\" What's imprecise about this statement?", options: ["Nothing — this is an accurate description", "The minimum necessary standard is codified in the HIPAA Privacy Rule (45 CFR §164.502(b)/§164.514(d)), not the Security Rule, even though access control design is one of the main ways it's operationally satisfied", "HIPAA has no minimum necessary standard at all", "The minimum necessary standard only applies to paper records, not ePHI"], answerIndex: 1, explanation: "Minimum necessary is a Privacy Rule term, a sibling regulation to the Security Rule — commonly blurred together but formally distinct." },
    { id: "cmp-10", type: "scenario", question: "Riverside Health wants to satisfy HIPAA's minimum necessary standard for clinician access to patient charts without giving every clinician blanket access to every patient. Which concept from this course's authorization-models chapter is the natural fit for implementing this concretely?", options: ["A flat ACL granting all clinicians the same fixed permission set", "A relationship-based access control (ReBAC) model that grants chart access only while an active clinician-patient care-team relationship exists", "A single shared \"clinician\" role with no further distinctions", "Removing audit logging to simplify access decisions"], answerIndex: 1, explanation: "Minimum necessary is the compliance requirement; care-team ReBAC is one concrete way to implement it." },
    { id: "cmp-11", type: "scenario", question: "An investigation at Riverside Health finds that three nurses on a shift share one login account to save time between patient rounds. Which specific HIPAA Security Rule requirement does this violate?", options: ["Audit controls (§164.312(b))", "Unique user identification, a required implementation specification under access control (§164.312(a))", "Data minimization", "The right to erasure"], answerIndex: 1, explanation: "Unique user identification requires every user to have their own distinct identifier, never a shared login." },
    { id: "cmp-12", type: "concept", question: "PCI-DSS Requirement 10 represents which IAM concept under a different name?", options: ["Least privilege", "Multi-factor authentication", "Accounting / audit trail", "Data minimization"], answerIndex: 2, explanation: "Requirement 10 (\"track and monitor all access\") is accounting/audit trail by PCI-DSS's own name." },
    { id: "cmp-13", type: "scenario", question: "At Meridian Trust, the tellers who process routine deposits and the staff who approve outbound wire transfers have deliberately different access profiles, even though both work in retail banking operations. Which PCI-DSS requirement is this separation most directly satisfying, and which IAM principle does it map to?", options: ["Requirement 10; accounting", "Requirement 8; authentication", "Requirement 7; least privilege (restricting access by business need-to-know)", "Requirement 3; encryption at rest"], answerIndex: 2, explanation: "Requirement 7's need-to-know restriction is least privilege by PCI-DSS's own name." },
    { id: "cmp-14", type: "scenario", question: "Meridian Trust requires every employee logging into any system that touches cardholder data to use MFA, not just a password. Which PCI-DSS requirement specifically mandates this, and which earlier chapter already covered the underlying mechanism?", options: ["Requirement 7; chapter 6 (authorization models)", "Requirement 8; chapter 5 (authentication factors & MFA)", "Requirement 12; chapter 9 (threat landscape)", "Requirement 1; chapter 4 (directory services)"], answerIndex: 1, explanation: "Requirement 8 mandates MFA for all access into the Cardholder Data Environment; chapter 5 covers MFA mechanics." },
    { id: "cmp-15", type: "compare", question: "Compare ISO/IEC 27001's 2013 and 2022 editions in terms of Annex A structure.", options: ["Both editions have identical Annex A numbering; only the main clauses changed", "The 2013 edition had 114 controls across 14 categories; the 2022 edition reorganized this into 93 controls across 4 themes, renumbering access-control content into the 5.x/8.x ranges", "The 2022 edition added 50 new controls not present in 2013", "ISO 27001 has never had an Annex A; that's a feature unique to ISO 27002"], answerIndex: 1, explanation: "The 2022 edition cut Annex A from 114 controls/14 categories to 93 controls/4 themes, with access-control content moving into the 5.x/8.x ranges." },
    { id: "cmp-16", type: "concept", question: "In ISO/IEC 27001:2022's Annex A, which control covers identity management specifically, as distinct from the overarching access control policy?", options: ["A.5.15", "A.5.16", "A.8.2", "A.8.5"], answerIndex: 1, explanation: "A.5.15 is the overarching access control policy; A.5.16 is identity management specifically." },
    { id: "cmp-17", type: "bug", question: "A specialist reviews a client's Statement of Applicability and sees it cites \"A.9.4.1 — Information access restriction\" as evidence of their current ISO 27001 certification. What should the specialist check before accepting this?", options: ["Nothing — A.9.4.1 is valid in every edition of ISO 27001", "Whether the document is citing the 2013 edition's numbering (which the 2022 edition renumbered, e.g., into the 8.x range) rather than confirming current 2022-edition compliance", "Whether the client has ever read the standard at all", "Whether A.9.4.1 refers to a PCI-DSS requirement instead"], answerIndex: 1, explanation: "A.9.4.1 is 2013-edition numbering; the 2022 edition renumbered this content, so the citation needs checking against the edition actually in force." },
    { id: "cmp-18", type: "scenario", question: "Northwind Apps needs SOC 2 so enterprise buyers will sign contracts, and also has GDPR exposure because of its EU customers. What does this combination illustrate about real-world compliance work?", options: ["Organizations only ever need to satisfy one framework, chosen based on industry", "Commercial requirements (like a customer demanding a SOC 2 report) and legal requirements (like GDPR, triggered by data subject location) can both apply to the same organization simultaneously, and a specialist must map actual data/people populations against all applicable frameworks rather than assuming a single one", "GDPR only applies to companies headquartered in the EU", "SOC 2 compliance automatically satisfies GDPR requirements"], answerIndex: 1, explanation: "Real organizations commonly carry overlapping legal and commercial compliance obligations simultaneously." },
    { id: "cmp-19", type: "bug", question: "A vendor's marketing page states: \"As required under the newly finalized 2025 HIPAA Security Rule overhaul, all covered entities must now implement mandatory encryption with no addressable exceptions.\" What's the problem with this claim, based on this chapter's research?", options: ["Nothing — the overhaul was finalized exactly as described", "As of this chapter's research, the January 2025 NPRM proposing that overhaul had not been finalized, with its target final-action date having already slipped toward 2027 — the claim treats a proposal as if it were already law", "HIPAA has never proposed any changes to encryption requirements", "The Security Rule does not cover encryption at all, so the claim is unrelated"], answerIndex: 1, explanation: "The 2025 NPRM is still a proposal, not a final rule, as of the research done for this chapter." },
    { id: "cmp-20", type: "compare", question: "Compare GDPR's data minimization principle with PCI-DSS's Cardholder Data Environment (CDE) scoping practice.", options: ["They are unrelated concepts from entirely different domains with no common theme", "Both are, at heart, strategies for reducing exposure — GDPR by limiting what personal data is collected/retained in the first place, PCI-DSS by limiting which systems are considered in-scope for cardholder data — even though one is a legal principle and the other an audit-scoping practice", "GDPR data minimization is a subset of PCI-DSS Requirement 7", "PCI-DSS CDE scoping is the IAM concept being referred to when GDPR says \"lawful basis\""], answerIndex: 1, explanation: "Both principles reduce exposure/risk by shrinking scope, even though they come from different regulatory traditions." }
  ],

  "iam-market-landscape": [
    { id: "mkt-01", type: "concept", question: "What is the key difference between Workforce IAM and CIAM?", options: ["Workforce IAM manages a bounded, HR-backed population of an organization's own people; CIAM manages an unbounded, self-registering population of external customers at consumer scale", "Workforce IAM only applies to on-premises directories; CIAM only applies to cloud directories", "CIAM is a subset of Workforce IAM used for contractors", "There is no meaningful difference; the terms are interchangeable"], answerIndex: 0, explanation: "Workforce IAM's population roughly tracks headcount and is HR-backed; CIAM's population is unbounded and self-registering, at a very different scale." },
    { id: "mkt-02", type: "concept", question: "What does PAM (Privileged Access Management) specifically add on top of ordinary authentication and authorization?", options: ["A faster login page for executives", "Credential vaulting, session recording, and just-in-time privilege elevation for the highest-risk accounts", "Social login buttons for consumer apps", "A replacement for multi-factor authentication"], answerIndex: 1, explanation: "PAM targets the smaller, higher-risk slice of privileged accounts with vaulting, recording, and JIT elevation — distinct from everyday AuthN/AuthZ." },
    { id: "mkt-03", type: "concept", question: "Why does this chapter only reference IGA rather than redefining it?", options: ["IGA isn't a real market category", "Chapter 10 already owns the full definition of IGA as a governance/process discipline; this chapter only discusses IGA as a tooling/market category to avoid duplicating that definition", "IGA was renamed to PAM", "Keycloak implements IGA natively, so no separate definition is needed"], answerIndex: 1, explanation: "The course avoids duplicate definitions across chapters; ch10 owns IGA's definition, ch12 only discusses the tooling category." },
    { id: "mkt-04", type: "concept", question: "Which of these is an example of a privileged account in the PAM sense?", options: ["A help-desk agent who can reset passwords for one department", "A regular employee's email login", "A domain-controller admin account with broad access across the network", "A customer's self-registered account on a public website"], answerIndex: 2, explanation: "Scope and blast radius determine 'privileged' status, not just the word 'admin' — a domain-controller admin is privileged; a narrowly-scoped help-desk admin is not, in the PAM sense." },
    { id: "mkt-05", type: "concept", question: "What is just-in-time (JIT) privilege elevation designed to reduce?", options: ["The number of MFA prompts a user sees", "The length of time an elevated permission exists, shrinking how long a compromised credential would be dangerous", "The cost of a SaaS subscription", "The number of applications an SSO session covers"], answerIndex: 1, explanation: "JIT elevation grants elevated access for a limited window tied to a task, instead of standing privileged access held permanently." },
    { id: "mkt-06", type: "compare", question: "How does 'open-source vs. commercial IAM' differ as an axis from 'self-hosted vs. SaaS/managed IAM'?", options: ["They are the same axis described two different ways", "Open-source vs. commercial is about licensing/cost model; self-hosted vs. SaaS is about who operates the running system — a commercial product can still be self-hosted, and some open-source projects are offered as managed SaaS", "Open-source products can never be self-hosted", "SaaS products are always open-source"], answerIndex: 1, explanation: "These are genuinely separate axes: licensing model vs. operational responsibility. A commercial product can be self-hosted; an open-source product can be consumed as a managed SaaS offering." },
    { id: "mkt-07", type: "concept", question: "Why is 'Keycloak has no license fee' an incomplete answer to 'which is cheaper overall'?", options: ["Keycloak actually does have a license fee", "Total cost of ownership also includes operational expertise, infrastructure, patching, and tuning labor that a self-hosted deployment must supply itself", "SaaS products are always cheaper regardless of scale", "License fees are the only real cost in any IAM system"], answerIndex: 1, explanation: "TCO is the right lens — 'free to license' doesn't mean 'cheap overall' once operational burden is counted." },
    { id: "mkt-08", type: "concept", question: "What is data residency, in the IAM context?", options: ["How long a user session stays active before timing out", "Where identity data is physically stored and which jurisdiction's laws govern it", "The number of data centers a vendor operates", "A synonym for vendor lock-in"], answerIndex: 1, explanation: "Data residency concerns the physical location and governing jurisdiction of identity data, a real driver toward self-hosting for regulated organizations." },
    { id: "mkt-09", type: "scenario", question: "Northwind Apps runs a multi-tenant B2B SaaS product with thousands of end-customer logins across many tenant companies. Which market category does it most likely need first?", options: ["PAM", "IGA", "CIAM", "A directory service only"], answerIndex: 2, explanation: "Northwind's consumer-scale, self-registering end-customer population is a textbook CIAM shape." },
    { id: "mkt-10", type: "scenario", question: "Riverside Health, a hospital network under HIPAA, is weighing a self-hosted Keycloak deployment against a commercial SaaS workforce IAM product. What is the strongest category-specific reason it might lean toward self-hosting?", options: ["Self-hosting is always cheaper in absolute dollar terms", "Data residency and regulatory control concerns push it toward wanting full visibility into where identity data lives", "SaaS products cannot support MFA", "CIAM products are mandatory under HIPAA"], answerIndex: 1, explanation: "HIPAA-driven data-residency and control concerns are a real, defensible reason to prefer self-hosting, independent of raw cost comparisons." },
    { id: "mkt-11", type: "scenario", question: "Meridian Trust, a retail bank, has workforce IAM in place for everyday employee access to internal systems. A security review finds that admins with direct access to core banking infrastructure have no session recording or time-boxed elevation. What gap does this describe?", options: ["A CIAM gap", "A missing PAM layer on top of its existing workforce IAM", "A missing MFA requirement", "An IGA access-certification gap only"], answerIndex: 1, explanation: "Workforce IAM answers 'who is this and what role do they hold'; it doesn't by itself vault, record, or time-box the smaller set of highest-risk privileged sessions — that's PAM's job." },
    { id: "mkt-12", type: "scenario", question: "A team says, 'We already have Okta for workforce SSO, so we don't need to evaluate anything else for privileged admin access to our production database.' What is wrong with this reasoning?", options: ["Nothing — workforce IAM always covers privileged access needs too", "Workforce IAM and PAM are different market categories solving different problems; having one doesn't imply the other is covered", "Okta cannot be used for workforce SSO", "PAM is only relevant for IGA-regulated industries"], answerIndex: 1, explanation: "This is the chapter's core pitfall: 'we have IAM' doesn't answer 'do we have PAM' — they're separate purchases solving different problems." },
    { id: "mkt-13", type: "concept", question: "As of this chapter's live research (November 2026), what is the current corporate/branding relationship between Auth0 and Okta?", options: ["Auth0 was spun off from Okta into an independent company in 2026", "Auth0 remains part of Okta (acquired 2021); current branding is 'Okta Customer Identity Cloud, powered by Auth0' / 'Auth0 by Okta,' with product/engineering orgs unifying further in 2026", "Auth0 was acquired by Microsoft in 2026", "Auth0 and Okta have always been fully separate companies"], answerIndex: 1, explanation: "The 2021 acquisition stands; what changed in 2026 was branding/org structure, not ownership." },
    { id: "mkt-14", type: "concept", question: "What is the current, live-verified status of ForgeRock relative to Ping Identity, and why does this chapter hedge on part of it?", options: ["ForgeRock was shut down entirely in 2023", "ForgeRock was acquired by Thoma Bravo and folded into Ping Identity (settled fact), but how far the product-line/brand merge has gone is disputed across sources, so the chapter states that honestly rather than asserting a specific integration depth", "ForgeRock acquired Ping Identity", "ForgeRock and Ping Identity remain entirely unrelated companies"], answerIndex: 1, explanation: "The acquisition itself is settled; the degree of product/brand integration is genuinely ambiguous in current sources, which the chapter flags rather than guessing." },
    { id: "mkt-15", type: "concept", question: "What is Microsoft's current branding for its identity product, as of November 2026?", options: ["Azure Active Directory (Azure AD)", "Microsoft Entra ID — unchanged since its 2023 rename from Azure AD, with no further rebrand found", "Microsoft Identity Cloud", "Windows Active Directory Online"], answerIndex: 1, explanation: "The 2023 Azure AD → Microsoft Entra ID rename is still current; no evidence of a further rebrand as of this chapter's research." },
    { id: "mkt-16", type: "concept", question: "What is the single most surprising, easy-to-miss corporate fact this chapter's live research turned up in the PAM category?", options: ["CyberArk went out of business in 2025", "Palo Alto Networks acquired CyberArk in February 2026 and rebranded the product line 'Idira' in May 2026 — most practitioners still say 'CyberArk,' but the current corporate/product name has changed", "BeyondTrust acquired CyberArk", "CyberArk merged with SailPoint to form a combined PAM/IGA company"], answerIndex: 1, explanation: "This is confirmed across multiple independent sources (including Palo Alto Networks' own site) and is flagged in the chapter as the most consequential fact to get right." },
    { id: "mkt-17", type: "compare", question: "Why does this chapter name both SailPoint and Saviynt for the IGA category, and both CyberArk/Idira and BeyondTrust for PAM, rather than naming one clear 'winner' for each?", options: ["Because the course avoids being specific about anything", "Because no neutral, up-to-date source found in live research named one undisputed market leader for 2026 in either category — naming both candidates honestly reflects that rather than asserting a precise ranking the research couldn't confirm", "Because SailPoint and Saviynt are actually the same company", "Because PAM and IGA are the same market category"], answerIndex: 1, explanation: "This follows the course's no-invented-facts discipline: when sources disagree or can't confirm a clean 'winner,' the chapter says so rather than asserting a precise claim." },
    { id: "mkt-18", type: "scenario", question: "An organization is deciding between Keycloak and a commercial SaaS IAM product. It has a small team with limited time to run new infrastructure, wants extremely fast time-to-value, and is willing to pay a premium to avoid operational work. Which choice does this chapter suggest fits better, and why?", options: ["Keycloak, because it's free to license", "A commercial SaaS alternative, because it outsources operational burden in exchange for subscription cost — exactly the trade-off this organization is describing wanting", "Neither — the organization should build its own IAM system from scratch", "Keycloak, because commercial products cannot be trusted with sensitive data"], answerIndex: 1, explanation: "The chapter's honest framing: Keycloak suits orgs with (or willing to build) real operational capacity; commercial SaaS suits orgs that want to pay to outsource that burden entirely — this scenario describes the latter." }
  ],

  "oauth2-core": [
    { id: "oac-01", type: "concept", question: "Which OAuth 2.0 role is best described as \"a protected API\"?", options: ["Resource Owner", "Client", "Authorization Server", "Resource Server"], answerIndex: 3, explanation: "Resource Server hosts protected resources and accepts requests bearing an access token — in plain terms, an API." },
    { id: "oac-02", type: "concept", question: "Which OAuth 2.0 role most closely maps onto chapter 7's Identity Provider (IdP)?", options: ["Resource Owner", "Client", "Authorization Server", "Resource Server"], answerIndex: 2, explanation: "The Authorization Server authenticates the resource owner and issues tokens — roughly the IdP function, though the mapping isn't a clean 1:1 rename." },
    { id: "oac-03", type: "compare", question: "Chapter 7's IdP/SP/RP vocabulary has no named equivalent for which OAuth 2.0 role?", options: ["Authorization Server, because it's identical to IdP", "Resource Owner and Resource Server, because SSO/federation never needed to name the end user or a protected API as formal roles", "Client, because SP and RP already cover it exactly", "All four roles have exact chapter 7 equivalents"], answerIndex: 1, explanation: "OAuth introduces Resource Owner (the end user, named directly because OAuth is a delegation protocol) and Resource Server (a protected API) — neither has a chapter 7 equivalent." },
    { id: "oac-04", type: "scenario", question: "Northwind Apps is registering a new OAuth client for an enterprise customer's dashboard integration. The customer asks Northwind to accept any redirect_uri under *.customer-co.example for convenience during setup. What should Northwind's security team do?", options: ["Approve it — broader patterns are fine as long as the domain is correct", "Refuse, and register only the exact, full callback URL the dashboard will actually use", "Approve it only if the customer uses HTTPS", "Approve it but require client authentication instead"], answerIndex: 1, explanation: "RFC 6749 requires exact, simple-string-comparison redirect URI matching specifically because anything broader lets an attacker who controls any page under that domain hijack a real user's authorization code." },
    { id: "oac-05", type: "scenario", question: "Meridian Trust's mobile banking app uses the authorization code flow with PKCE. Why is PKCE valuable here even though the app also uses TLS everywhere?", options: ["PKCE replaces the need for TLS", "PKCE protects against a different threat: if the authorization code itself is intercepted (e.g. by another app on the same device via a custom URL scheme), it's useless without the matching code_verifier, which was never transmitted", "PKCE is only relevant for client-credentials grants", "PKCE prevents the access token from expiring"], answerIndex: 1, explanation: "PKCE closes the code-interception gap specifically — the verifier never travels in plaintext until the final token exchange, so an intercepted code alone isn't enough." },
    { id: "oac-06", type: "bug", question: "A Riverside Health engineer debugging a clinician-portal login notices the access_token appears directly in the browser's URL fragment immediately after the redirect, with no separate code-exchange step. What's the most likely cause?", options: ["Correct authorization code flow behavior", "The app is using the deprecated Implicit grant, which returns the token directly in the fragment instead of an intermediate code", "A PKCE misconfiguration", "A client_credentials misconfiguration"], answerIndex: 1, explanation: "The Implicit grant skips the code-exchange step and puts the access token straight into the redirect URL's fragment — exactly the symptom described, and one reason it's now discouraged." },
    { id: "oac-07", type: "scenario", question: "A new Riverside Health patient-portal SPA needs to log users in via OAuth without a backend that could hold a client secret. Which combination is the current best-practice choice?", options: ["Resource Owner Password Credentials, since there's no secret to protect anyway", "Implicit grant, since it's designed for browsers", "Authorization code flow with PKCE, treating the SPA as a public client", "Client credentials grant, impersonating the logged-in user"], answerIndex: 2, explanation: "Authorization code + PKCE is exactly the pattern designed for public clients that can't hold a secret safely, and is current best practice regardless." },
    { id: "oac-08", type: "concept", question: "What specifically does PKCE protect against?", options: ["Weak passwords at the authorization server's login page", "An intercepted authorization code being redeemed for tokens by someone other than the client that requested it", "Expired access tokens being accepted", "Resource servers accepting tokens from the wrong issuer"], answerIndex: 1, explanation: "PKCE's whole point is binding the eventual code exchange to whoever holds the original code_verifier, so an intercepted code alone isn't redeemable." },
    { id: "oac-09", type: "concept", question: "In the authorization code flow, which value is exchanged at the token endpoint, and which never leaves the browser's redirect?", options: ["The access token is exchanged at the token endpoint; the authorization code stays in the browser", "The authorization code is exchanged, server-to-server, at the token endpoint for an access token; only the short-lived code ever appears in the browser's redirect", "Both the code and the access token travel through the browser", "Neither travels through the browser — both are sent server-to-server from the start"], answerIndex: 1, explanation: "The browser only ever sees the short-lived code; the actual access token exchange happens over a direct, server-to-server call to the token endpoint." },
    { id: "oac-10", type: "bug", question: "A token endpoint returns the identical {\"error\":\"invalid_grant\"} for a bad authorization code, a reused code, and a wrong PKCE verifier. Is this a bug?", options: ["Yes — it should return a distinct error for each case to help debugging", "No — returning a generic error for all three is a deliberate choice, since a more specific error would help an attacker determine which part of a forged request is wrong", "Yes — it violates the OAuth 2.0 spec", "No, but only because PKCE is optional"], answerIndex: 1, explanation: "A token endpoint intentionally collapses distinct failure causes into one generic error to avoid leaking information useful to an attacker probing a forged request." },
    { id: "oac-11", type: "scenario", question: "Northwind's security team is reviewing a candidate authorization server that validates redirect_uri by checking whether the submitted value starts with the registered one, rather than exact string comparison. What's the concrete risk?", options: ["None — prefix matching is equivalent to exact matching in practice", "An attacker who controls any path extending the registered prefix (e.g. a sibling route, a misconfigured subpath) could receive a real user's authorization code and exchange it for tokens issued in that user's name", "It only affects client_credentials grants, not authorization code", "It would cause logins to fail entirely"], answerIndex: 1, explanation: "Prefix/substring matching lets anything sharing that prefix qualify as a valid destination — exactly the gap RFC 6749's exact-match requirement exists to close." },
    { id: "oac-12", type: "concept", question: "Per RFC 6749 §3.1.2.3, how must an authorization server compare a submitted redirect_uri against a fully-registered redirect URI?", options: ["Case-insensitive domain match only", "Same-origin check (scheme + host)", "Simple string comparison — an exact match", "Substring containment is sufficient"], answerIndex: 2, explanation: "RFC 6749 §3.1.2.3 requires the authorization server to compare the two URIs using simple string comparison when the full redirect URI was registered — an exact match, not a looser check." },
    { id: "oac-13", type: "scenario", question: "Meridian Trust needs its nightly batch-reporting service to call an internal API with no human user involved at any point. Which OAuth grant type fits?", options: ["Authorization code with PKCE", "Implicit grant", "Client credentials grant", "Device authorization grant"], answerIndex: 2, explanation: "Client credentials is the machine-to-machine grant: the client authenticates as itself with no resource owner or browser step at all — exactly this scenario." },
    { id: "oac-14", type: "compare", question: "What's the key difference between the client credentials grant and the device authorization grant?", options: ["Client credentials needs a browser; device code doesn't", "Client credentials involves no resource owner or browser at all; device code involves a human approving a code on a separate device that does have a browser", "They're the same grant under two names", "Device code is for confidential clients only; client credentials is for public clients only"], answerIndex: 1, explanation: "Client credentials is pure machine-to-machine with no human step; device code specifically exists for devices without a usable browser, requiring a human to approve on a second device." },
    { id: "oac-15", type: "scenario", question: "Riverside Health is building a CLI tool for lab technicians with no browser available on the terminal it runs on. Which grant type, previewed in this chapter and covered in full in chapter 14, fits this case?", options: ["Resource Owner Password Credentials", "Implicit grant", "Device authorization grant", "Authorization code without PKCE"], answerIndex: 2, explanation: "Device authorization grant is designed exactly for this: the CLI tool displays a code, and the technician approves it on a separate device with a browser." },
    { id: "oac-16", type: "concept", question: "What is the relationship between a PKCE code_verifier and code_challenge?", options: ["They are the same value, just named differently", "code_challenge is an encrypted version of code_verifier that the server can decrypt", "code_challenge = base64url(SHA-256(code_verifier)) under the S256 method — a one-way derivation that cannot be reversed", "code_verifier is derived from code_challenge after login"], answerIndex: 2, explanation: "Under S256, the challenge is a one-way SHA-256 hash of the verifier, base64url-encoded — it can be checked against a verifier but never reversed back into one." },
    { id: "oac-17", type: "bug", question: "A developer sets code_challenge_method=plain and sets code_challenge equal to code_verifier directly, reasoning \"it's simpler and still checks the value matches.\" What's wrong with this?", options: ["Nothing — plain is just as secure as S256", "Under \"plain,\" the challenge sent in the clear in the authorize request IS the verifier itself — so anyone who intercepts the authorize request already has the verifier, defeating PKCE's entire purpose", "plain mode is rejected by all authorization servers", "This only matters for confidential clients"], answerIndex: 1, explanation: "The plain method sends the verifier itself as the challenge, visible in the authorize request — exactly the value PKCE is supposed to keep secret until the token exchange, so it offers no real protection if that initial request is observed." },
    { id: "oac-18", type: "scenario", question: "After learning that a public demo authorization server didn't enforce exact-match redirect_uri validation for one of its clients — and that an authorization code could be redirected to an attacker-controlled domain and exchanged for real tokens — what's the correct lesson for Northwind Apps to take into its own production client registrations?", options: ["Public demo servers are never a useful reference, so the finding is irrelevant", "Exact-match redirect_uri validation is a real, exploitable security control, not a formality — Northwind must ensure its own Authorization Server enforces it strictly, since a loosely configured one would permit the identical attack against real user accounts", "The finding proves PKCE is unnecessary if redirect_uri validation exists", "The finding only applies to the client_credentials grant"], answerIndex: 1, explanation: "The live finding is a concrete demonstration of exactly what RFC 6749's exact-match requirement is meant to prevent — a production system without strict enforcement is genuinely exploitable, not just theoretically non-compliant." }
  ],

  "oauth2-extended": [
    { id: "oax-01", type: "concept", question: "Why does the device authorization grant need no registered redirect_uri at all?", options: ["Because it doesn't use HTTPS", "Because the interactive step happens entirely on a separate, browser-capable device the user already has, not on the constrained device itself", "Because device flow doesn't support scopes", "Because the device client always has a client secret"], answerIndex: 1, explanation: "The constrained device never receives a browser redirect at all — a second device handles login/approval and the first device only ever talks to the token endpoint directly." },
    { id: "oax-02", type: "scenario", question: "A CLI tool polls the token endpoint during a device-flow login and gets back {\"error\": \"authorization_pending\"}. What should the CLI do?", options: ["Abort immediately and show an error to the user", "Treat it as the expected, normal response and keep polling at the server-advertised interval", "Immediately retry as fast as possible to beat a race condition", "Fall back to the authorization code flow"], answerIndex: 1, explanation: "authorization_pending is the expected response on every poll until the human finishes logging in and approving — not a failure." },
    { id: "oax-03", type: "bug", question: "A device-flow client ignores a slow_down response and keeps polling at its original rate. What is the likely consequence, per RFC 8628?", options: ["Nothing — slow_down is purely informational", "The client should expect further rate-limiting or its device code being invalidated", "The access token will be issued faster", "The client's client_id will be permanently revoked"], answerIndex: 1, explanation: "RFC 8628 expects a client to back off its polling interval after receiving slow_down; ignoring it risks further throttling or an invalidated code." },
    { id: "oax-04", type: "concept", question: "What distinguishes the client credentials grant from every other OAuth grant covered in this course so far?", options: ["It requires a refresh token", "It has no resource owner at all — the client authenticates as itself, with no user context in the request", "It can only be used over HTTP, not HTTPS", "It always issues an ID token"], answerIndex: 1, explanation: "Client credentials is pure machine-to-machine: the request identifies the client, not any user, because there is no user." },
    { id: "oax-05", type: "scenario", question: "Meridian Trust's nightly fraud-scoring job calls the core banking ledger service with no human involved. Which grant type fits, and why?", options: ["Authorization code with PKCE, because it's the most secure option", "Client credentials, because this is exactly the no-resource-owner, service-to-service case it exists for", "Device authorization grant, because the job runs on a server with no browser", "Implicit grant, because it's the simplest"], answerIndex: 1, explanation: "No user is involved at all — one internal service calling another is the textbook client credentials use case, contrasted directly with chapter 13's user-present authorization code flow." },
    { id: "oax-06", type: "compare", question: "How does an access token obtained via client credentials typically differ from one obtained via a user-present flow, at the claims level?", options: ["It has no exp claim", "It typically has no sub claim identifying a human subject — it identifies the client instead (e.g. client_id)", "It is always a reference token", "It cannot be introspected"], answerIndex: 1, explanation: "A client credentials token represents the client itself, not a user — there is no resource owner to put in a sub claim." },
    { id: "oax-07", type: "concept", question: "What does an RFC 7662 token introspection response's active field mean?", options: ["Whether the token was ever issued by this specific client", "Whether the authorization server currently considers the token valid", "Whether the token has a refresh_token attached", "Whether the token was issued less than a minute ago"], answerIndex: 1, explanation: "active is the central fact introspection exists to report: is this token still good, right now, according to the authorization server." },
    { id: "oax-08", type: "bug", question: "Introspecting a token string that the authorization server has never issued returns {\"active\": false} with almost no other fields, while introspecting a real expired token returns the full claim set plus active:false. Why the difference in response shape?", options: ["It's a bug in most implementations", "RFC 7662 deliberately keeps the unknown-token response minimal so the endpoint can't be used to fish for information about which tokens are real", "Expired tokens are always reference tokens", "Only JWTs get the full claim set back"], answerIndex: 1, explanation: "Minimizing the response for unrecognized tokens prevents using introspection as an oracle to discover valid token values." },
    { id: "oax-09", type: "scenario", question: "A team revokes a compromised access token via the revocation endpoint and gets back HTTP 200. They tell their incident commander 'access was cut off immediately.' What should be verified before accepting that claim?", options: ["Nothing — HTTP 200 always means the token stopped working", "Whether the token was a reference (server-tracked) token or a self-contained JWT — only the former is guaranteed to actually stop working immediately", "Whether the token had an aud claim", "Whether the client used HTTP Basic or POST body authentication"], answerIndex: 1, explanation: "RFC 7009 permits returning 200 even when nothing was actually invalidated; a self-contained JWT with no server-side record may keep reporting active:true until it naturally expires." },
    { id: "oax-10", type: "bug", question: "This chapter's own lab revoked a self-contained JWT access token via /connect/revocation (got HTTP 200), then immediately introspected the same token and got active:true. What explains this, precisely?", options: ["The revocation call failed silently", "The authorization server never stored a server-side record of that specific token to delete, so introspection re-checked only the token's own signature and expiry, both still valid", "Introspection always ignores revocation", "The wrong client credentials were used for introspection"], answerIndex: 1, explanation: "A self-contained JWT carries its own proof and typically has no corresponding server-side row — there's nothing for revocation to delete, so introspection (checking signature + exp) still reports it valid." },
    { id: "oax-11", type: "compare", question: "Why does a reference (opaque) access token revoke more reliably than a self-contained JWT access token?", options: ["Reference tokens are encrypted and JWTs are not", "A reference token's validity is backed by a real server-side record that revocation can delete; introspecting it after deletion correctly finds nothing. A JWT's validity is self-proven by its own signature, with nothing server-side to delete.", "JWTs cannot be introspected at all", "Reference tokens never expire"], answerIndex: 1, explanation: "The difference is architectural: one design relies on a server-side lookup (deletable), the other relies on self-contained cryptographic proof (nothing to delete)." },
    { id: "oax-12", type: "concept", question: "What problem does token exchange (RFC 8693) solve that neither client credentials nor the device flow addresses?", options: ["Issuing the very first token in a session", "Letting a client trade an existing token for a new one — e.g. with a narrower scope/audience (downscoping), or to let one service act for another", "Encrypting a token's claims", "Rotating a signing key"], answerIndex: 1, explanation: "Token exchange is specifically about converting one already-issued token into another, differently-scoped or differently-actored one." },
    { id: "oax-13", type: "compare", question: "What is the practical difference between delegation and impersonation as token-exchange outcomes (RFC 8693)?", options: ["Delegation issues a longer-lived token than impersonation", "Delegation keeps an act claim showing who is really acting on a subject's behalf; impersonation drops it, making the new request indistinguishable from the original subject's own", "Impersonation is only available to public clients", "There is no real difference — they are two names for the same mechanism"], answerIndex: 1, explanation: "The act claim is the entire distinction: delegation preserves traceability of who is really making the downstream call, impersonation erases it." },
    { id: "oax-14", type: "bug", question: "A chapter covering token exchange wants to include a live lab against the demo server used throughout Part III. What should it do, given that server's discovery document does not list a token-exchange grant in grant_types_supported?", options: ["Simulate the request and present invented but plausible-looking output", "Say plainly that no live lab exists for this piece and cover the mechanism conceptually only, grounded in the RFC", "Skip the topic entirely without explanation", "Use a different, undocumented endpoint on the same server to fake the behavior"], answerIndex: 1, explanation: "This course's no-invented-facts rule requires saying so honestly rather than fabricating a lab the server doesn't actually support." },
    { id: "oax-15", type: "scenario", question: "Northwind Apps builds northwind-cli, a terminal tool with no embedded browser, for customers to manage their tenant config. Why is the device authorization grant a better fit than embedding a static long-lived API key in the tool?", options: ["Because device flow is faster to implement", "Because a static long-lived key in a CLI tool installed on many laptops/build servers is a large, hard-to-revoke blast radius if one copy leaks, while device flow issues a short-lived, revocable access token (and a server-tracked refresh token) per login instead", "Because device flow doesn't require any authentication at all", "Because static API keys are not supported by OAuth"], answerIndex: 1, explanation: "Device flow avoids embedding a permanent secret in software distributed to many machines, trading it for a per-session, more easily revoked credential." },
    { id: "oax-16", type: "concept", question: "In a device authorization grant, what is the purpose of the interval field returned alongside the device_code and user_code?", options: ["It sets how long the access token will be valid once issued", "It tells the polling device the minimum number of seconds to wait between token-endpoint polling attempts", "It sets the expiry of the user_code only, not the device_code", "It specifies how many scopes can be requested"], answerIndex: 1, explanation: "interval is the server's instruction for polling frequency; ignoring it risks a slow_down response or worse." }
  ],

  "openid-connect": [
    { id: "oidc-01", type: "concept", question: "What does OpenID Connect add on top of plain OAuth 2.0?", options: ["A completely different set of grant types that replace OAuth's", "An identity layer: the openid scope, the ID token, discovery, and UserInfo, built on OAuth's existing grants", "A mandatory requirement that all tokens be encrypted rather than signed", "A replacement for the access token that removes the need for scopes"], answerIndex: 1, explanation: "OIDC is additive. It reuses OAuth's grants unchanged and adds the openid scope, the ID token, a discovery document, and the UserInfo endpoint." },
    { id: "oidc-02", type: "scenario", question: "A developer at Meridian Trust fetches their OIDC provider's discovery document before writing any integration code. Which of these can that single JSON response tell them?", options: ["Only the authorization_endpoint, nothing else", "The authorization, token, userinfo, and jwks endpoints, plus supported scopes and claims", "The actual password hash algorithm used by the provider", "The private signing key used to sign ID tokens"], answerIndex: 1, explanation: "The discovery document exposes endpoint URLs and capability lists (scopes_supported, claims_supported, etc.) — never private keys or credential internals." },
    { id: "oidc-03", type: "concept", question: "Which claims must always be present in a valid ID token, independent of which scopes were requested?", options: ["name, email, picture", "iss, sub, aud, exp, iat", "preferred_username, email_verified", "tenant_id, subscription_tier"], answerIndex: 1, explanation: "iss, sub, aud, exp, and iat are the minimum claims OIDC Core requires on every ID token so it is independently verifiable; profile/email claims only appear if those scopes were requested." },
    { id: "oidc-04", type: "concept", question: "Why does an ID token carry an aud (audience) claim naming the client itself?", options: ["So a resource server can safely accept it in place of an access token", "So a verifier (and a careful resource server) can tell an ID token apart from an access token and reject it if it is presented where an access token is expected", "Because aud is required by TLS, not by OIDC", "To let any application on the internet reuse the token freely"], answerIndex: 1, explanation: "An ID token's audience is the client, not an API — exactly the detail that should make a resource server reject it if someone mistakenly sends an ID token instead of an access token." },
    { id: "oidc-05", type: "concept", question: "What does the email_verified claim specifically distinguish?", options: ["Whether the user has two-factor authentication enabled", "Whether the email address was confirmed through a verification flow, versus merely typed into a form", "Whether the email scope was requested at all", "Whether the user's account is currently active"], answerIndex: 1, explanation: "email_verified is a separate signal from the mere presence of an email claim — it answers whether that address was actually confirmed, not just supplied." },
    { id: "oidc-06", type: "scenario", question: "Northwind Apps checks its OIDC provider's claims_supported list and finds no \"department\" claim listed anywhere. What is the correct way to get that data into a logged-in user's tokens?", options: ["Request a scope called department and hope the provider honors it", "Nothing can be done; claims_supported is fixed forever", "Ask the provider to define and advertise a custom claim (in Keycloak, via a client scope's protocol mapper)", "Decode the JWT header instead of the payload"], answerIndex: 2, explanation: "claims_supported is an advertised ceiling set by the provider. A client cannot invent a claim by requesting an arbitrary scope — the provider must add and advertise it." },
    { id: "oidc-07", type: "scenario", question: "Meridian Trust's integration team adds a nonce value to their authorization request and later checks that the same value comes back in the ID token. What is that check protecting against?", options: ["Encrypting the ID token payload", "Confirming the returned ID token was actually issued in response to this specific request, as a replay/mix-up defense", "Setting the token's expiry time", "Requesting the refresh token grant"], answerIndex: 1, explanation: "A client-supplied nonce, echoed back unchanged in the ID token, lets the client confirm the token corresponds to the request it actually sent." },
    { id: "oidc-08", type: "compare", question: "What is the key functional difference between reading a claim from an already-held ID token versus calling the UserInfo endpoint for the same claim?", options: ["UserInfo claims are always encrypted and ID token claims never are", "They are entirely different datasets with no overlap", "Reading the ID token is free (no network call) but only as fresh as login time; UserInfo requires a live call but reflects current data", "UserInfo only works for machine-to-machine clients"], answerIndex: 2, explanation: "Both paths return the same underlying claims, filtered by the same requested scopes — the trade-off is freshness (UserInfo) versus zero extra network cost (ID token)." },
    { id: "oidc-09", type: "compare", question: "How does chapter 7's general metadata concept map onto this chapter's content?", options: ["It doesn't relate at all — metadata was only ever a SAML concept", "The OIDC discovery document is the concrete, JSON implementation of the general metadata/trust idea introduced in chapter 7", "Metadata refers only to HTTP response headers in OIDC", "Metadata and the ID token are the same thing"], answerIndex: 1, explanation: "Chapter 7 defined metadata generally as a machine-readable description of endpoints/capabilities exchanged to establish trust; OIDC's discovery document is exactly that, implemented concretely." },
    { id: "oidc-10", type: "scenario", question: "Riverside Health's patient portal requests openid profile email at login and wants to greet the patient by name immediately after the redirect back, with no extra API call. Where should it read preferred_username from?", options: ["A separate call to the token introspection endpoint", "The ID token it already received in the token response", "The jwks_uri endpoint", "A hardcoded default value"], answerIndex: 1, explanation: "Because profile was requested, preferred_username rides inside the ID token already returned — no second call is needed, which is exactly why the portal can render immediately." },
    { id: "oidc-11", type: "scenario", question: "A patient at Riverside Health clicks an email verification link in a second browser tab while their portal session (and its already-issued ID token) is still open in the first tab. The portal wants to show the up-to-date verification status. What should it do?", options: ["Trust the ID token's email_verified value forever, since it was true at login", "Call the UserInfo endpoint to get a fresh email_verified value, since the ID token's claim is only as current as the moment it was issued", "Discard the session and force a full re-login", "Ignore the claim entirely since it cannot change"], answerIndex: 1, explanation: "An ID token's claims are a snapshot from login time. A live UserInfo call is exactly the mechanism OIDC provides for getting current data without a full re-authentication." },
    { id: "oidc-12", type: "scenario", question: "Northwind Apps wants every connected customer application to know which customer tenant a logged-in user belongs to, without a second API call after login. What is the right mechanism?", options: ["Ask the user to type their tenant ID into a form every time", "Add a custom tenant_id claim via a Keycloak client scope's protocol mapper, so it rides inside the ID token", "Store the tenant ID only in a database the client has no access to", "Request the tenant OAuth scope, which is a standard scope"], answerIndex: 1, explanation: "tenant_id is not a standard OIDC claim, so it has to be added and advertised by the provider — a Keycloak protocol mapper on a client scope is exactly how that is configured." },
    { id: "oidc-13", type: "scenario", question: "A developer at Northwind Apps hardcodes the authorization, token, and UserInfo endpoint URLs for a customer's OIDC provider directly into the client config, rather than fetching the discovery document. Six months later the provider migrates to a new domain and all three URLs change. What breaks, and why?", options: ["Nothing breaks — OIDC endpoints never change", "The integration breaks because the hardcoded URLs are now stale; fetching discovery at startup would have picked up the new URLs automatically", "Only the ID token stops working, not the access token", "The client automatically redirects to the new domain because of DNS"], answerIndex: 1, explanation: "Discovery exists specifically so a client never has to hardcode endpoint URLs — exactly the failure mode avoided by fetching the document instead." },
    { id: "oidc-14", type: "scenario", question: "A client at Meridian Trust successfully exchanges a device code for tokens, including an access token scoped with only api (no openid). It then calls the UserInfo endpoint with that access token and gets a 401 invalid_token. What is the most likely cause?", options: ["The UserInfo endpoint is down", "The access token was never issued with the openid scope, so it was never entitled to call an OIDC-specific endpoint in the first place", "The device code expired before the token exchange", "The client used the wrong HTTP method"], answerIndex: 1, explanation: "A perfectly valid OAuth access token issued without the openid scope is not entitled to UserInfo — this is one of the two most common causes of a UserInfo 401 in practice." },
    { id: "oidc-15", type: "scenario", question: "During this chapter's own research, a live curl request to https://demo.duendesoftware.com/connect/userinfo with no Authorization header at all returned which status and header?", options: ["200 OK with an empty JSON object", "401, with a WWW-Authenticate header naming error=invalid_token", "302 redirect to the login page", "500 Internal Server Error"], answerIndex: 1, explanation: "Confirmed live: calling UserInfo with no token, or an invalid one, returns 401 with a WWW-Authenticate: Bearer realm=\"IdentityServer\",error=\"invalid_token\" header — a well-formed rejection, not a crash or silent success." },
    { id: "oidc-16", type: "scenario", question: "A reader runs this chapter's device-flow lab and polls the token endpoint before completing the login step in their browser. What response should they expect?", options: ["An empty 200 OK response", "HTTP 400 with {\"error\": \"authorization_pending\"}", "A fully issued access token immediately", "A permanent 403 Forbidden"], answerIndex: 1, explanation: "Confirmed live for this chapter: polling before the human login step completes returns a specific, well-defined 400 authorization_pending error, not a generic failure." },
    { id: "oidc-17", type: "concept", question: "Which of these is a standard OIDC scope with a fixed, spec-defined bundle of claims?", options: ["tenant_id", "department", "profile", "subscription_tier"], answerIndex: 2, explanation: "profile (along with openid and email) is one of OIDC's standard scopes, unlocking a fixed, spec-defined set of claims like name, given_name, and preferred_username. The others are examples of custom, provider-defined claims." },
    { id: "oidc-18", type: "compare", question: "Chapter 13/14 covered OAuth 2.0's access and refresh tokens in depth. What is genuinely new about the ID token this chapter introduces, as opposed to just another renamed access token?", options: ["Nothing — an ID token is just an access token with a different name", "The ID token is specifically about proving who authenticated (identity), carries standardized identity claims, and is scoped to the client itself rather than a resource server — a different purpose from an access token's authorization role", "ID tokens never expire, unlike access tokens", "ID tokens are only issued for machine-to-machine clients"], answerIndex: 1, explanation: "The ID token is OIDC's distinct contribution: a token about identity and authentication, not API authorization, with its own standardized claim set and its own audience (the client itself)." }
  ],

  "jwt-and-crypto": [
    { id: "jwt-01", type: "concept", question: "What does JWS (JSON Web Signature) actually protect?", options: ["Confidentiality — nobody but the recipient can read the payload", "Integrity and authenticity — the payload is still readable, but tampering is detectable", "Nothing by default; it only works combined with JWE", "The transport channel the token travels over"], answerIndex: 1, explanation: "JWS proves a payload hasn't been altered and, for asymmetric algorithms, who signed it. It does not hide the payload — that's JWE's job." },
    { id: "jwt-02", type: "concept", question: "A token uses JWS, not JWE. Which statement is correct?", options: ["The payload is ciphertext and requires a decryption key to read", "The payload is base64url-encoded JSON, readable by anyone who has the token", "The header is encrypted but the payload is not", "JWS tokens cannot carry claims at all"], answerIndex: 1, explanation: "Base64url is a reversible encoding, not encryption. Anyone holding a JWS token can decode its header and payload." },
    { id: "jwt-03", type: "bug", question: "An engineer at Northwind Apps adds a customer's internal discount code directly into an access token's payload as a custom claim, reasoning 'it's inside the token, so only our API can see it.' What's wrong?", options: ["Nothing — JWTs are encrypted by default so the claim is safe", "The claim is base64url-encoded, not encrypted; anyone who obtains the token (browser dev tools, a proxy log) can decode it in seconds", "JWTs can't carry custom claims, so the code would be silently dropped", "The problem is only that the claim name wasn't namespaced"], answerIndex: 1, explanation: "This is the classic 'JWT is automatically encrypted' misconception. A JWS payload is plain, readable JSON once decoded." },
    { id: "jwt-04", type: "concept", question: "A JWT's compact serialization is made of which three segments, joined by dots?", options: ["issuer.subject.audience", "header.payload.signature", "kid.alg.sig", "claims.key.hash"], answerIndex: 1, explanation: "header.payload.signature, each independently base64url-encoded." },
    { id: "jwt-05", type: "concept", question: "Why can't you meaningfully 'decode' a JWT's signature segment the way you can its header and payload?", options: ["The signature segment is also JSON but uses a different schema", "The signature is opaque bytes produced by a cryptographic operation, not JSON — it's checked by recomputing and comparing, not decoded for meaning", "Only the payload is base64url-encoded; the signature uses plain base64", "The signature segment is actually a second copy of the payload, encrypted"], answerIndex: 1, explanation: "Header and payload decode to JSON because that's what was encoded. The signature is raw cryptographic output — verified by recomputation, never decoded into meaning." },
    { id: "jwt-06", type: "concept", question: "What is a JWK (JSON Web Key)?", options: ["A one-time code used during the device authorization grant", "A single cryptographic key represented as a JSON object, carrying its type, use, algorithm, key id, and key material", "A hashed version of a client secret", "The JSON Web Key is another name for the whole JWT"], answerIndex: 1, explanation: "A JWK (RFC 7517) is one key as JSON. A JWKS is a set of them." },
    { id: "jwt-07", type: "concept", question: "On the live Duende demo server, where does a client learn the URL of the JWKS endpoint without hardcoding it?", options: ["It's only documented in the server's source code", "The jwks_uri field inside the OIDC discovery document (/.well-known/openid-configuration)", "It's always exactly /jwks on every OIDC server by spec, no discovery needed", "Inside every access token's header as a claim"], answerIndex: 1, explanation: "Confirmed live: the discovery document's jwks_uri field resolves to https://demo.duendesoftware.com/.well-known/openid-configuration/jwks." },
    { id: "jwt-08", type: "scenario", question: "A verifier receives a JWT whose header contains kid: '0202F0E3BCADB53E5E62DBBF25BC31FC'. What does the verifier do with that value?", options: ["Ignores it and always uses whichever key is listed first in the JWKS response", "Uses it to find the JWK in the fetched JWKS response whose own kid matches, then uses that key's material to check the signature", "Treats it as the signature itself", "Uses it as a cache key only, unrelated to which key verifies the token"], answerIndex: 1, explanation: "kid-based lookup is exactly what lets a verifier pick the one correct key out of a JWKS response that may list several." },
    { id: "jwt-09", type: "concept", question: "Why does kid-based key lookup specifically matter for making key rotation possible?", options: ["It lets JWKS responses stay small by listing only one key at a time", "It lets multiple keys coexist in a JWKS response at once, so tokens signed with an older key keep verifying while newer tokens use a new key", "It removes the need for a JWKS endpoint entirely", "It allows a verifier to skip signature verification for trusted kid values"], answerIndex: 1, explanation: "Without kid, a verifier would have no principled way to know which of several published keys applies to a given token during an overlap period." },
    { id: "jwt-10", type: "scenario", question: "Meridian Trust suspects one of its signing keys was compromised. Relative to the four revocation mitigations chapter 8 introduced, what is key rotation here actually doing?", options: ["Revoking one specific stolen access token without affecting any others", "Invalidating every token signed with the compromised key at once — a blunt instrument, but the right tool when the key itself, not one token, is the thing that's compromised", "Nothing — rotation only applies to refresh tokens, never access tokens", "Permanently disabling the entire authentication system until a new deployment ships"], answerIndex: 1, explanation: "Signing-key rotation is blunt by nature: it invalidates everything signed with the retired key, not a single token — which is exactly appropriate when the key itself is suspect." },
    { id: "jwt-11", type: "scenario", question: "Put these key-rotation steps in the order they must happen to avoid an outage: (1) retire the old key from JWKS, (2) publish the new key into JWKS, (3) start signing new tokens with the new key.", options: ["1, 2, 3", "2, 3, 1", "3, 2, 1", "2, 1, 3"], answerIndex: 1, explanation: "Publish the new key first (so verifiers can already find it), then start signing with it, then retire the old key only once every token it signed has expired." },
    { id: "jwt-12", type: "bug", question: "A team rotates keys by immediately removing the old key from JWKS the moment they start signing with the new key, skipping any overlap period. What breaks?", options: ["Nothing breaks; removing the old key immediately is best practice", "Every still-valid, unexpired token that was signed with the old key now fails verification, because its kid no longer matches anything in JWKS", "Only refresh tokens are affected, never access tokens", "The new key stops working until the old key is restored"], answerIndex: 1, explanation: "This is exactly the overlap-period pitfall: removing the old key too early breaks verification for tokens that are still legitimately in use." },
    { id: "jwt-13", type: "compare", question: "Compare HS256 (symmetric) and RS256 (asymmetric) signing: which one can safely have its verification key published at a public JWKS endpoint, and why?", options: ["Both can be published safely — JWKS is designed for either", "Only RS256 — its public key can only verify signatures, never create valid ones, unlike an HS256 shared secret which can do both", "Only HS256 — RSA keys are too large to publish in JSON", "Neither — JWKS only works with elliptic-curve algorithms"], answerIndex: 1, explanation: "Publishing an HS256 secret hands out forging ability, not just verification. RS256's public key is safe to publish precisely because it can't be used to forge a signature." },
    { id: "jwt-14", type: "concept", question: "Why would publishing an HMAC (HS256) secret at a JWKS-style public endpoint be a serious mistake?", options: ["It would make verification slightly slower for everyone", "The same secret used to verify a signature is also the secret needed to create one, so publishing it hands out forging capability, not just verification", "JWKS endpoints technically can't contain HMAC keys at all, so it would just fail silently", "It would only be a mistake if the secret were also used as a database password"], answerIndex: 1, explanation: "Symmetric algorithms use one key for both directions — that's the whole reason asymmetric algorithms (RS256/ES256), not HS256, are the ones meant to have a public verification key published." },
    { id: "jwt-15", type: "concept", question: "What is 'algorithm confusion' as a JWT security issue?", options: ["A user being confused about which OAuth grant type to use", "A verifier that trusts the alg value from an untrusted token's own header rather than enforcing an algorithm it already expects, which an attacker can exploit to forge a token", "A client sending a token with a typo in the algorithm name", "A server supporting too many algorithms, making audits slow"], answerIndex: 1, explanation: "Named here, with full defenses deferred to chapter 18: never derive the expected algorithm from the untrusted token itself." },
    { id: "jwt-16", type: "scenario", question: "Riverside Health's patient portal caches a JWKS response at service startup and never refreshes it. What's the risk, specifically tied to key rotation?", options: ["No risk — JWKS responses never change once published", "If the IdP rotates its signing key after the cache was fetched, tokens signed with the new key will fail verification until the service refreshes its cache and picks up the new kid", "The cached response would cause every token to be accepted without verification", "The risk only applies to refresh tokens, not ID tokens"], answerIndex: 1, explanation: "A verifier needs to periodically refresh its cached JWKS (or refresh on a kid miss) specifically so it can pick up new keys introduced during rotation." }
  ],

  "saml2": [
    { id: "saml-01", type: "concept", question: "What does the <saml:Subject> element of a SAML assertion most directly provide?", options: ["Identifies who the assertion is about via NameID, and binds it to this exchange via SubjectConfirmation", "Lists the bindings the IdP supports", "Declares the assertion's validity window", "Specifies which attributes the IdP is willing to share"], answerIndex: 0, explanation: "Subject carries the NameID (who this is about) and SubjectConfirmation (ties the assertion to this specific browser exchange). Validity windows live in Conditions, not Subject." },
    { id: "saml-02", type: "scenario", question: "A Northwind Apps SP receives a SAML assertion from an enterprise customer's IdP and checks the <Conditions><AudienceRestriction> before trusting it. What is this check specifically protecting against?", options: ["An assertion issued for a different SP being replayed and accepted here", "The user's password being too weak", "The assertion being too old to parse", "The IdP's certificate being self-signed"], answerIndex: 0, explanation: "AudienceRestriction names exactly which SP may accept the assertion, preventing cross-SP replay of an assertion issued for someone else." },
    { id: "saml-03", type: "scenario", question: "Riverside Health's EHR vendor's SP only checks that a SAML Response arrived over HTTPS from Riverside's known IdP hostname, and never validates the embedded XML signature. What risk does this create?", options: ["A forged or tampered assertion could be accepted as genuine, since TLS alone doesn't verify who authored the assertion content", "None — TLS already guarantees the assertion's authenticity", "This only matters for IdP-initiated flows", "SAML assertions aren't signed, so there's nothing to validate"], answerIndex: 0, explanation: "Transport security (TLS) and assertion-signature validation are different checks. Skipping signature validation means the SP is trusting the network path, not the actual issuer of the XML content." },
    { id: "saml-04", type: "concept", question: "Which binding typically carries the initial SAML AuthnRequest from SP to IdP, and why?", options: ["HTTP-Redirect, because the request is small enough to fit as a URL parameter", "HTTP-POST, because browsers can't process redirects", "The SOAP binding, because it requires full web-services machinery", "The Artifact binding, because requests must always be looked up out-of-band"], answerIndex: 0, explanation: "AuthnRequests are small, so Redirect's URL-parameter transport is simple and sufficient." },
    { id: "saml-05", type: "scenario", question: "Meridian Trust's IdP engineer is configuring the binding for the assertion response, which will include several AttributeStatement entries about the employee. Which binding should be used, and why?", options: ["HTTP-POST, because signed assertions with attributes routinely exceed practical URL length limits", "HTTP-Redirect, because it's faster for large payloads", "Either binding works identically regardless of payload size", "Neither — assertions must use SOAP"], answerIndex: 0, explanation: "POST carries the message via an auto-submitting form with no practical size ceiling, unlike Redirect's URL-parameter transport." },
    { id: "saml-06", type: "scenario", question: "A Meridian Trust engineer sees a SAML integration fail intermittently with 'URL too long' errors, and only for users with many group memberships. What's the most likely cause?", options: ["The assertion response is being sent over the HTTP-Redirect binding instead of HTTP-POST", "The user's NameID format is invalid", "The IdP's signing certificate expired", "The SP's ACS URL is misconfigured"], answerIndex: 0, explanation: "More attributes/groups means a larger assertion; carrying it over Redirect's URL-length-limited transport is the classic cause of this exact symptom." },
    { id: "saml-07", type: "compare", question: "Which pairing correctly matches a SAML concept to its closest OIDC equivalent?", options: ["saml:Assertion ↔ ID Token", "saml:Assertion ↔ Access Token", "EntityDescriptor ↔ Client Secret", "AttributeStatement ↔ Redirect URI"], answerIndex: 0, explanation: "Both the SAML assertion and the OIDC ID token are the IdP's signed statement of who the user is." },
    { id: "saml-08", type: "compare", question: "SAML metadata and the OIDC discovery document serve the same underlying purpose. What's the key practical difference?", options: ["SAML metadata is XML typically exchanged once during integration setup; OIDC discovery is JSON typically fetched live over HTTP by the RP", "SAML metadata is never signed, while OIDC discovery always is", "OIDC has no equivalent of metadata at all", "SAML metadata is fetched per-login, while discovery is exchanged once during setup"], answerIndex: 0, explanation: "Same job (describe endpoints/capabilities), different wire format and exchange pattern." },
    { id: "saml-09", type: "scenario", question: "Northwind Apps is integrating with a large enterprise customer whose IT team hands over a metadata XML file and says 'configure SSO from this.' What should Northwind's engineer expect to find inside it?", options: ["The customer IdP's entityID, its signing certificate, and its SSO endpoint URLs for each supported binding", "An export of the customer's user database", "A list of OAuth scopes the customer supports", "The customer's internal firewall rules"], answerIndex: 0, explanation: "SAML metadata (EntityDescriptor) describes exactly this: identity, certificate, and endpoints — not user data or firewall config." },
    { id: "saml-10", type: "concept", question: "What distinguishes SP-initiated from IdP-initiated SAML SSO?", options: ["Whether an AuthnRequest precedes the assertion response, or the Response arrives unsolicited", "Whether the assertion is signed", "Whether HTTP-POST or HTTP-Redirect is used for the response", "Whether the user authenticates with MFA"], answerIndex: 0, explanation: "SP-initiated: SP sends an AuthnRequest first. IdP-initiated: the IdP sends an unsolicited Response with no preceding request." },
    { id: "saml-11", type: "scenario", question: "Riverside Health's intranet portal lists every connected clinical system as a clickable tile; clicking one logs the clinician straight into that system, with Riverside's IdP never having received a request from it first. Which flow is this?", options: ["IdP-initiated SSO", "SP-initiated SSO", "OAuth client credentials grant", "LDAP federation"], answerIndex: 0, explanation: "The login originates at the IdP's own portal with no preceding AuthnRequest — the defining shape of IdP-initiated SSO." },
    { id: "saml-12", type: "scenario", question: "Riverside Health's security team reviews IdP-initiated SSO logins from the intranet portal and asks why these are considered harder to protect against replay than SP-initiated logins. What's the accurate answer?", options: ["There's no AuthnRequest to correlate the Response against via InResponseTo, so the SP must rely more heavily on Conditions validation", "IdP-initiated assertions are never signed", "IdP-initiated flows don't use TLS", "There's no concept of assertion expiry in IdP-initiated flows"], answerIndex: 0, explanation: "Without a prior request to correlate against, the SP's main defense is strict Conditions (validity window, audience) checking — not request correlation." },
    { id: "saml-13", type: "scenario", question: "A Meridian Trust security reviewer asks whether the bank should drop SAML entirely in favor of OIDC across every integration. Which answer best reflects accurate, current industry practice?", options: ["No — SAML remains widely used in long-lived enterprise/legacy integrations and migrating working, certified integrations has real cost; OIDC is preferred for new builds but doesn't make existing SAML integrations obsolete", "Yes — OASIS formally deprecated SAML and it must no longer be used", "Yes — SAML cannot be used securely under PCI-DSS", "No — OIDC cannot be used for enterprise SSO at all"], answerIndex: 0, explanation: "SAML hasn't been deprecated; it coexists with OIDC, with a large installed base in legacy/regulated/long-lived federations." },
    { id: "saml-14", type: "concept", question: "Why does this chapter not include a hands-on curl-based lab, unlike chapters 13-15?", options: ["Real SAML exchanges require XML signing, canonicalization, and signature validation against a trust anchor — mechanics curl can't exercise without a full SAML library", "There is no live public test IdP available anywhere for SAML", "Keycloak doesn't support SAML", "The OASIS specification prohibits hands-on testing of SAML"], answerIndex: 0, explanation: "SAML's XML-signing/validation requirements are heavier than a curl-only lab can reasonably cover — an honest scoping choice, not a gap." },
    { id: "saml-15", type: "scenario", question: "Riverside Health's EHR vendor's SP receives a SAML assertion whose AudienceRestriction names a completely different SP's entityID. What should happen, and why?", options: ["The SP should reject the assertion — AudienceRestriction exists specifically to stop an assertion issued for one SP from being accepted by another", "The SP should accept it, since AudienceRestriction only matters for IdP-initiated flows", "The SP should accept it as long as the signature is valid", "The SP should accept it and relabel the assertion for its own entityID"], answerIndex: 0, explanation: "A mismatched AudienceRestriction is exactly the scenario this field exists to catch; accepting it anyway defeats its purpose regardless of signature validity." },
    { id: "saml-16", type: "compare", question: "Which statement correctly compares SAML's role vocabulary to OIDC's?", options: ["SAML calls the relying application the SP; OIDC calls the same role the RP — they're the same role under two protocol-specific names, not two different architectures", "SAML's SP and OIDC's RP are unrelated concepts", "OIDC has no relying-role concept at all", "SAML's SP is actually the same thing as the IdP"], answerIndex: 0, explanation: "Chapter 7 established this: SP and RP name the same role, just under different protocol vocabularies." },
    { id: "saml-17", type: "scenario", question: "Northwind Apps integrates with an enterprise customer's SAML IdP that returns a NameID with Format urn:oasis:names:tc:SAML:1.1:nameid-format:persistent instead of an email address. What does this tell Northwind about how to identify the user?", options: ["The NameID is an opaque, stable identifier that isn't necessarily human-readable or an email — Northwind should key its local account mapping on this value rather than assume it's an email", "Authentication failed", "The IdP doesn't support attributes", "The assertion is unsigned"], answerIndex: 0, explanation: "NameID format varies by declaration; a persistent-format NameID is a stable opaque value, not guaranteed to be an email address." },
    { id: "saml-18", type: "concept", question: "Which statement best distinguishes an AuthnStatement from an AttributeStatement inside a SAML assertion?", options: ["AuthnStatement records that and how authentication happened (when, by what method); AttributeStatement carries additional, optional user attributes", "AuthnStatement is optional; AttributeStatement is mandatory", "They are two names for the same element", "AuthnStatement carries user attributes; AttributeStatement records the authentication method"], answerIndex: 0, explanation: "AuthnStatement is about the authentication event itself; AttributeStatement (optional) is about additional data on the user." }
  ],

  "oauth-oidc-security": [
    { id: "sec-01", type: "concept", question: "What is the current status of the OAuth 2.0 Security Best Current Practice document?", options: ["Still an early-stage IETF draft, not yet stable enough to cite by number", "A published, final RFC — RFC 9700, also catalogued as BCP 240", "Withdrawn and replaced entirely by RFC 6819", "Published only as a vendor whitepaper, never formally standardized"], answerIndex: 1, explanation: "RFC 9700 / BCP 240 was published in January 2025 and is the final, consolidated Best Current Practice — not a draft." },
    { id: "sec-02", type: "concept", question: "Why does RFC 9700 recommend PKCE even for confidential clients, which already hold a client secret?", options: ["Because client secrets are being deprecated entirely", "Because PKCE replaces the need for a redirect URI", "Because the client secret only protects the token-endpoint exchange, not the authorization code while it's in transit", "Because confidential clients are no longer allowed to use the authorization code grant"], answerIndex: 2, explanation: "A stolen authorization code can't be redeemed without the original code_verifier, a layer the client secret never covered — it only matters one step later, at the token endpoint." },
    { id: "sec-03", type: "scenario", question: "Revisiting Northwind Apps' chapter 9 incident: an enterprise customer's integration had an XSS flaw, and the attacker read the bearer token Northwind had issued. Which single architectural change to that integration would have prevented the token from being readable, even with the XSS flaw still present?", options: ["Increasing the token's scope so it covers more resources", "Switching the authorization grant from authorization code to client credentials", "Keeping the token somewhere JavaScript cannot read it at all, such as behind a BFF or in an httpOnly cookie instead of localStorage", "Adding a longer client secret to the integration's backend"], answerIndex: 2, explanation: "The XSS flaw gave the injected script the same privileges as legitimate page code; if the token had been held outside JS-readable storage, that script would have had nothing to steal." },
    { id: "sec-04", type: "scenario", question: "Meridian Trust's client application is configured to accept logins from both Meridian's own realm and a partner bank's authorization server. An attacker who compromises the partner bank's server tries to trick the client into sending a code issued by Meridian's real server to the attacker's server instead. What is this attack called?", options: ["Credential stuffing", "A mix-up attack", "MFA fatigue", "A brute-force attack"], answerIndex: 1, explanation: "A mix-up attack exploits a client trusting more than one authorization server with no reliable way to tell which one actually issued a given response." },
    { id: "sec-05", type: "bug", question: "A client generates a random state value for each authorization request and checks that the callback's state matches what was sent, but stores the expected value in a global JavaScript variable readable by any script on the page. What's wrong with this implementation?", options: ["Nothing — state only needs to be random, not protected after generation", "The value isn't bound securely to the initiating browser session, so its CSRF protection is effectively decorative", "state should never be stored anywhere, only transmitted", "The bug is that state should be a fixed, predictable value instead of random"], answerIndex: 1, explanation: "state's security property comes from being bound to the session that initiated the request; storing it somewhere any page script (including injected script) can read or tamper with defeats that binding." },
    { id: "sec-06", type: "compare", question: "Compare storing an access token in localStorage versus in an httpOnly cookie. Which statement is accurate?", options: ["Both are equally exposed to XSS, since both are accessible from any script on the page", "localStorage is JavaScript-readable (exposed to XSS); an httpOnly cookie is not JS-readable but is auto-attached by the browser, reintroducing CSRF exposure", "httpOnly cookies are exposed to XSS in the same way localStorage is", "localStorage is immune to XSS because it is origin-scoped"], answerIndex: 1, explanation: "Each storage choice trades one exposure category for another: localStorage trades CSRF-safety for XSS-readability; httpOnly cookies trade XSS-readability for CSRF exposure that needs its own defense." },
    { id: "sec-07", type: "concept", question: "What does iss validation (per RFC 9207) require the client to check?", options: ["That the access token's audience claim matches the resource server", "That the authorization response's iss value matches the issuer identifier the client expected, aborting on any mismatch", "That the redirect URI uses HTTPS", "That the client secret was transmitted over TLS"], answerIndex: 1, explanation: "The authorization server states its own identity via the iss parameter; the client must compare it to the expected issuer before proceeding, which is exactly the check a mix-up attack defeats if it's missing." },
    { id: "sec-08", type: "scenario", question: "Riverside Health's patient portal is being updated to let patients authenticate either through Riverside's own identity provider or through a partner lab's IdP, side by side in the same client. What risk does this specific setup introduce that a single-IdP client wouldn't have?", options: ["Credential stuffing becomes impossible to defend against", "A mix-up attack becomes possible, since the client now has to correctly tell two authorization servers' responses apart", "MFA fatigue attacks become more likely", "The access token's lifetime automatically becomes longer"], answerIndex: 1, explanation: "Trusting more than one authorization server is exactly the precondition for a mix-up attack; iss validation (or, as a fallback, distinct redirect URIs per IdP) is the defense." },
    { id: "sec-09", type: "bug", question: "A developer argues: \"Our client is confidential and holds a secret, so we don't need PKCE.\" What's the flaw in that reasoning?", options: ["There is no flaw — confidential clients genuinely don't need PKCE under any current guidance", "The client secret protects the token-endpoint exchange, but does nothing to stop an attacker who intercepts the authorization code before it ever reaches that exchange", "PKCE is only relevant to the implicit grant, which confidential clients never use", "Confidential clients can't technically implement PKCE even if they wanted to"], answerIndex: 1, explanation: "RFC 9700 recommends PKCE for confidential clients too, precisely because it closes a gap (code interception) that the secret was never positioned to close." },
    { id: "sec-10", type: "concept", question: "What is the specific role of RFC 9207 in this chapter's guidance?", options: ["It defines the PKCE code_verifier/code_challenge mechanics", "It defines the iss authorization-response parameter that lets a client verify which authorization server actually issued a response", "It deprecates the implicit grant", "It defines the state parameter's CSRF semantics"], answerIndex: 1, explanation: "RFC 9207, \"OAuth 2.0 Authorization Server Issuer Identification,\" is the spec behind iss validation, RFC 9700's preferred mix-up-attack defense." },
    { id: "sec-11", type: "scenario", question: "Northwind Apps is evaluating a Backend-for-Frontend (BFF) architecture for a new customer-facing SPA, instead of having the SPA hold tokens itself. What does the BFF pattern specifically buy them, per RFC 10017?", options: ["Faster token issuance from the authorization server", "The token never reaches the browser or browser-visible JavaScript at all, removing the XSS-reads-the-token exposure as a category rather than just hardening where the token sits", "Automatic exemption from needing PKCE", "A longer-lived refresh token than other architectures allow"], answerIndex: 1, explanation: "RFC 10017 calls the BFF pattern \"strongly recommended for business applications\" specifically because the token-in-the-browser exposure is eliminated, not merely reduced." },
    { id: "sec-12", type: "compare", question: "Compare an httpOnly-cookie-based browser client against a full BFF architecture. Which is accurate?", options: ["They are identical in every respect; BFF is just a rebranding of httpOnly cookies", "In the plain httpOnly-cookie case the browser app can still hold the access token itself; in the full BFF case the token is held entirely server-side and the browser gets only a session cookie", "httpOnly cookies are less secure than storing the token in localStorage", "A full BFF cannot use cookies at all"], answerIndex: 1, explanation: "An httpOnly cookie alone protects a token from JS-reads if the token itself is in the cookie; the BFF pattern goes further by keeping the token server-side entirely and issuing the browser only a session cookie." },
    { id: "sec-13", type: "concept", question: "Why must the state value be bound to the specific browser session that initiated the authorization request, rather than just being random?", options: ["Randomness alone is sufficient; binding to a session adds nothing", "Without session binding, an attacker's own legitimately-generated state value could still pass a naive comparison check, since the client isn't verifying that the responding browser is the one that started the request", "Binding to a session is required only for public clients, not confidential ones", "state values expire automatically after being generated, making binding unnecessary"], answerIndex: 1, explanation: "The CSRF protection's actual strength comes from tying the expected value to the initiating session — a value stored unbound (e.g. readable by any script, or not scoped to that session) fails to prevent a forged callback from a different flow." },
    { id: "sec-14", type: "scenario", question: "An internal auditor at Meridian Trust flags that a teller-facing single-page application stores its OAuth access token in sessionStorage. Which remediation directly addresses the auditor's concern, per this chapter's guidance?", options: ["Increase the access token's lifetime so tellers are logged in longer", "Move the token to a location JavaScript cannot read — an httpOnly cookie or, more completely, a BFF — since sessionStorage is just as JS-readable as localStorage for the lifetime of the tab", "Switch the grant type from authorization code to device authorization", "No remediation is needed, since sessionStorage clears when the tab closes"], answerIndex: 1, explanation: "sessionStorage is still plain JavaScript-accessible storage; clearing on tab-close doesn't change that an XSS flaw during the session can read it just as it could read localStorage." },
    { id: "sec-15", type: "bug", question: "An authorization server in a client's trust list doesn't support the iss authorization-response parameter. Per RFC 9700, what fallback mix-up defense is described, and what is its explicit downside?", options: ["No fallback exists; the client simply cannot defend against mix-up attacks against that server", "Giving each trusted authorization server a distinct, dedicated redirect URI — described as a fallback to be used only when iss support isn't available, not the preferred mechanism", "Disabling PKCE for that specific authorization server", "Extending the access token's audience claim to cover both servers"], answerIndex: 1, explanation: "RFC 9700 §4.4.2.2 names distinct-redirect-URIs-per-AS as a weaker fallback, explicitly framed as a last resort relative to iss validation." },
    { id: "sec-16", type: "concept", question: "A colleague claims RFC 9700 makes PKCE mandatory for every OAuth client, confidential or public, with no distinction. Is this an accurate reading of the RFC?", options: ["Yes, RFC 9700 §2.1.1 uses MUST language for both client types equally", "No — RFC 9700 §2.1.1 says PKCE MUST be used by public clients, but is only RECOMMENDED (not MUST) for confidential clients", "No, RFC 9700 doesn't mention PKCE at all", "Yes, but only for clients using the implicit grant"], answerIndex: 1, explanation: "Several secondary sources overstate this as a blanket MUST; the RFC's actual normative language keeps public clients at MUST and confidential clients at RECOMMENDED — an important distinction when citing it precisely." }
  ]
};
